/*
 * Safely append formatted text to an existing string buffer.
 * - Avoids dangerous functions like sprintf/strcat.
 * - Ensures null-termination stays within the buffer.
 */
int safe_snprintf_cat(char *buf, size_t buf_size, const char *fmt, ...)
{
    size_t used = strnlen(buf, buf_size);       // Find current length safely
    assert(buf_size == 0 || used < buf_size);   // Buffer must be null-terminated

    if (used >= buf_size)                       // Extra runtime guard
        return -1;                              // Buffer already full / invalid

    va_list ap;
