// Secure key derivation using HKDF with a cryptographically strong random salt.
// This avoids CWE-760 (predictable salt) by never using constants, timestamps,
// user IDs, or other predictable values as the salt.
bool DeriveKeySecurely(const uint8_t *secret, size_t secretLen,
                       const uint8_t *info, size_t infoLen,
                       uint8_t *outKey, size_t outKeyLen)
{
    uint8_t salt[32];                               // 256‑bit salt
    if (RAND_bytes(salt, sizeof(salt)) != 1)        // CSRNG(32)
        return false;

    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, nullptr);
    if (!pctx) return false;

    bool ok = false;
    if (EVP_PKEY_derive_init(pctx) <= 0) goto end;
    if (EVP_PKEY_CTX_set_hkdf_md(pctx, EVP_sha256()) <= 0) goto end;
    if (EVP_PKEY_CTX_set1_hkdf_salt(pctx, salt, sizeof(salt)) <= 0) goto end;
    if (EVP_PKEY_CTX_set1_hkdf_key(pctx, secret, secretLen) <= 0) goto end;
    if (info && infoLen &&
        EVP_PKEY_CTX_add1_hkdf_info(pctx, info, infoLen) <= 0) goto end;
    if (EVP_PKEY_derive(pctx, outKey, &outKeyLen) <= 0) goto end;

    ok = true;
end:
    EVP_PKEY_CTX_free(pctx);
    OPENSSL_cleanse(salt, sizeof(salt));           // clear salt from memory
    return ok;
}

