// Fills `buf` with cryptographically strong random bytes.
inline void secureRandomBytes(void* buf, std::size_t len) {
#ifdef _WIN32
  HCRYPTPROV prov;
  if (!CryptAcquireContext(&prov, nullptr, nullptr,
                           PROV_RSA_FULL, CRYPT_VERIFYCONTEXT))
    throw std::runtime_error("CryptAcquireContext failed");
  if (!CryptGenRandom(prov, static_cast<DWORD>(len),
                      static_cast<BYTE*>(buf))) {
    CryptReleaseContext(prov, 0);
    throw std::runtime_error("CryptGenRandom failed");
  }
  CryptReleaseContext(prov, 0);
#else
  int fd = ::open("/dev/urandom", O_RDONLY | O_CLOEXEC);
  if (fd < 0) throw std::runtime_error("open /dev/urandom failed");
  std::size_t off = 0;
  while (off < len) {
    ssize_t r = ::read(fd, static_cast<unsigned char*>(buf) + off, len - off);
    if (r <= 0) { ::close(fd); throw std::runtime_error("read urandom failed"); }
    off += static_cast<std::size_t>(r);
  }
  ::close(fd);
#endif
}

