// Securely hash a password using a cryptographically strong random salt.
// Demonstrates how to avoid CWE-760 (no predictable salts).
std::vector<unsigned char> hashPassword(const std::string& password) {
    constexpr size_t SALT_LEN = 16;   // at least 128 bits
    constexpr size_t HASH_LEN = 32;   // e.g., 256-bit hash output

    std::array<unsigned char, SALT_LEN> salt{};
    if (RAND_bytes(salt.data(), SALT_LEN) != 1) {
        throw std::runtime_error("Failed to generate cryptographic salt");
    }

    // Concatenate salt || password as input to the hash
    std::vector<unsigned char> input;
    input.reserve(SALT_LEN + password.size());
    input.insert(input.end(), salt.begin(), salt.end());
    input.insert(input.end(), password.begin(), password.end());

    std::vector<unsigned char> hash(HASH_LEN);
    unsigned int outLen = 0;

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) throw std::runtime_error("Failed to create EVP_MD_CTX");

