        EVP_DigestUpdate(ctx, input.data(), input.size()) != 1 ||
        EVP_DigestFinal_ex(ctx, hash.data(), &outLen) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Hash computation failed");
    }
    EVP_MD_CTX_free(ctx);

    // Store/return both salt and hash; caller must persist the salt with the hash
    hash.insert(hash.begin(), salt.begin(), salt.end()); // [salt || hash]
    return hash;
}

