  gboolean ok = FALSE;

  /* Basic syntax check */
  if (!gst_uri_is_valid (user_uri))
    return FALSE;

  /* Normalize/resolve the URI first */
  normalized = gst_uri_normalize (user_uri);
  if (!normalized)
    return FALSE;

