/*
 * Secure pattern against CWE-918 (SSRF):
 * - Do NOT fetch directly from a user-supplied URL.
 * - Instead, always construct the final URL from a trusted base URL.
 * - Only use user input as a *path* or *filename*, after validation.
 */

#include <stdio.h>
#include <string.h>
#include <glib.h>

/* Trusted, server-side configured base URL (cannot be changed by user) */
static const char *TRUSTED_BASE_URL = "https://my.fancy.cdn/";

/* Very simple path validation: allow only alnum, '.', '-', '_', and '/' */
static gboolean
is_safe_path(const char *path)
{
	for (const char *p = path; *p; p++) {
		if (!(g_ascii_isalnum(*p) || *p == '.' || *p == '-' ||
		      *p == '_' || *p == '/'))
			return FALSE;
	}
	return TRUE;
}

/* Build a full URL from a trusted base and a validated relative path */
static gchar *
build_firmware_url(const char *user_path, GError **error)
{
	if (user_path == NULL || user_path[0] == '\0') {
		g_set_error(error, G_FILE_ERROR, G_FILE_ERROR_INVAL,
		            "Empty firmware path");
		return NULL;
	}

	/* Reject if user tries to provide a full URL or scheme */
	if (g_str_has_prefix(user_path, "http://") ||
	    g_str_has_prefix(user_path, "https://")) {
		g_set_error(error, G_FILE_ERROR, G_FILE_ERROR_INVAL,
		            "Absolute URLs are not allowed");
		return NULL;
	}

	if (!is_safe_path(user_path)) {
		g_set_error(error, G_FILE_ERROR, G_FILE_ERROR_INVAL,
		            "Invalid characters in firmware path");
		return NULL;
	}

	/* Construct final URL on the server side */
	return g_build_filename(TRUSTED_BASE_URL, user_path, NULL);
}

/* Example usage: user supplies "devices/fw/firmware.cab" (not a full URL) */
int
main(void)
{
	const char *user_input = "devices/fw/firmware.cab";  /* from client */
	g_autoptr(GError) error = NULL;
	g_autofree gchar *firmware_url = build_firmware_url(user_input, &error);

	if (firmware_url == NULL) {
		g_printerr("Error building URL: %s\n", error->message);
		return 1;
	}

	/* Safe: only contacts TRUSTED_BASE_URL, never arbitrary user URL */
	g_print("Fetching firmware from: %s\n", firmware_url);
	/* perform_secure_download(firmware_url); */

	return 0;
}

