int build_target_sockaddr(const char *ip_str, unsigned short port,
                          struct sockaddr_storage *out)
{
    struct sockaddr_in  *v4 = (struct sockaddr_in *)out;
    struct sockaddr_in6 *v6 = (struct sockaddr_in6 *)out;

