/*
 * Secure pattern to prevent SSRF:
 *  - Enforce address family and length
 *  - Reject multicast / loopback / private / disallowed ranges
 *  - Optionally enforce per-tenant / jail policy
 */
int secure_connect(int sockfd, const struct sockaddr *addr, socklen_t addrlen)
{
    const struct sockaddr_in *sin;
    uint32_t ip;
    int err;

    if (addrlen != sizeof(struct sockaddr_in))
        return EINVAL;

    sin = (const struct sockaddr_in *)addr;
    if (sin->sin_family != AF_INET)
        return EAFNOSUPPORT;

    ip = ntohl(sin->sin_addr.s_addr);

    /* Reject multicast: 224.0.0.0 – 239.255.255.255 */
    if ((ip & 0xF0000000U) == 0xE0000000U)
        return EAFNOSUPPORT;

    /* Reject loopback: 127.0.0.0/8 */
    if ((ip & 0xFF000000U) == 0x7F000000U)
        return EACCES;

    /* Reject RFC1918 private networks (example policy) */
    if (   (ip & 0xFF000000U) == 0x0A000000U        /* 10.0.0.0/8   */
        || (ip & 0xFFF00000U) == 0xAC100000U        /* 172.16.0.0/12*/
        || (ip & 0xFFFF0000U) == 0xC0A80000U)       /* 192.168.0.0/16*/
        return EACCES;

    /* Optional: enforce tenant/jail policy */
    err = prison_remote_ip4(get_current_cred(), &sin->sin_addr);
    if (err != 0)
        return err;

    return connect(sockfd, addr, addrlen);
}

