/*
 * Secure pattern to mitigate CWE-918 (SSRF) in a simple HTTP proxy.
 * - Only allows requests to a fixed internal backend (127.0.0.1:8080)
 * - Ignores any user-supplied host/URL for outbound connections
 */

#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define BACKEND_IP   "127.0.0.1"
#define BACKEND_PORT 8080

int forward_to_backend(const char *user_path) {
    int sockfd;
    struct sockaddr_in backend_addr;
    char request[512];

    // Build a constrained HTTP request: only path is user-controlled
    if (snprintf(request, sizeof(request),
                 "GET %s HTTP/1.1\r\nHost: %s\r\n\r\n",
                 user_path, BACKEND_IP) >= (int)sizeof(request)) {
        return -1; // path too long
    }

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) return -1;

    memset(&backend_addr, 0, sizeof(backend_addr));
    backend_addr.sin_family = AF_INET;
    backend_addr.sin_port   = htons(BACKEND_PORT);
    inet_pton(AF_INET, BACKEND_IP, &backend_addr.sin_addr);

    // Outbound connection is strictly pinned to 127.0.0.1:8080
    if (connect(sockfd, (struct sockaddr *)&backend_addr,
                sizeof(backend_addr)) < 0) {
        close(sockfd);
        return -1;
    }

    write(sockfd, request, strlen(request));
    /* ... read response from sockfd and return to caller ... */

    close(sockfd);
    return 0;
}

