/* Fill buf with cryptographically strong random bytes. */
int secure_random_bytes(uint8_t *buf, size_t len)
{
    size_t off = 0;
    ssize_t r;

#ifdef __linux__
    /* Prefer getrandom() when available (no file descriptor needed). */
    while (off < len) {
        r = getrandom(buf + off, len - off, 0);
        if (r > 0) {
            off += (size_t) r;
            continue;
        }
        if (errno == EINTR)
            continue;           /* retry on signal */
        if (errno == ENOSYS)
            break;              /* getrandom() not supported, fall back */
        return -1;              /* other errors are fatal */
    }
    if (off == len)
        return 0;
#endif

    /* Portable fallback: use /dev/urandom (cryptographically secure). */
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0)
        return -1;

    off = 0;
    while (off < len) {
        r = read(fd, buf + off, len - off);
        if (r > 0) {
            off += (size_t) r;
        } else if (r < 0 && errno == EINTR) {
            continue;           /* retry on signal */
        } else {
            close(fd);
            return -1;          /* failure */
        }
    }
    close(fd);
    return 0;
}

