EVP_PKEY *load_strong_rsa_key(const unsigned char *n_bin, size_t n_len,
                              const unsigned char *e_bin, size_t e_len)
{
    EVP_PKEY *pkey = NULL;
    RSA     *rsa  = NULL;
    BIGNUM  *n    = NULL;
    BIGNUM  *e    = NULL;

    /* Build BIGNUMs from raw modulus and exponent bytes */
    if ((n = BN_bin2bn(n_bin, (int)n_len, NULL)) == NULL ||
        (e = BN_bin2bn(e_bin, (int)e_len, NULL)) == NULL)
