/*
 * Secure encryption helper:
 * - Enforces strong key sizes (128/192/256 bits only)
 * - Uses AES in GCM mode (AEAD, modern and strong)
 * - Rejects weak or non-standard key lengths
 */
int encrypt_aes_gcm(const unsigned char *key, size_t key_len,
                    const unsigned char *iv,  size_t iv_len,
                    const unsigned char *plaintext, int plaintext_len,
                    unsigned char *ciphertext)
{
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = NULL;
    int len = 0, out_len = 0;

    /* Enforce strong, standard AES key lengths only */
    if (key_len == 16)      cipher = EVP_aes_128_gcm();
    else if (key_len == 24) cipher = EVP_aes_192_gcm();
    else if (key_len == 32) cipher = EVP_aes_256_gcm();
    else return -1;  /* Reject inadequate / non-standard key sizes */

    if (!(ctx = EVP_CIPHER_CTX_new())) return -2;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) goto err;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)iv_len, NULL) != 1) goto err;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv) != 1) goto err;

    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) goto err;
    out_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) goto err;
    out_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return out_len; /* Number of bytes written */

err:
    EVP_CIPHER_CTX_free(ctx);
    return -3;
}

