 * Note: Uses Windows CryptoAPI. Error handling is minimal for brevity.
 */

#include <windows.h>
#include <wincrypt.h>
#include <stdio.h>

int main(void)
{
    HCRYPTPROV hProv = 0;
    BYTE key[32];  /* 256-bit key for strong encryption */
    BOOL result;

    /* Acquire a cryptographic provider context */
    if (!CryptAcquireContext(
            &hProv,
            NULL,                  /* default key container */
            MS_ENH_RSA_AES_PROV,   /* enhanced provider supports strong algorithms */
            PROV_RSA_AES,
            CRYPT_VERIFYCONTEXT))  /* no need to persist keys */
    {
        fprintf(stderr, "CryptAcquireContext failed: %lu\n", GetLastError());
        return 1;
