// Secure random byte generator using strong OS entropy sources
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>

#if __has_include(<sys/random.h>)
#include <sys/random.h>
#endif

// Fills buf with buflen cryptographically strong random bytes.
// Returns 0 on success, -1 on any failure.
int secure_random_bytes(void *buf, size_t buflen)
{
    unsigned char *p = buf;
    ssize_t n;

#if __has_include(<sys/random.h>)
    // Preferred: getrandom() / getentropy() when available
    while (buflen > 0) {
        n = getrandom(p, buflen, 0);
        if (n < 0) {
            if (errno == EINTR) continue;   // retry on signal
            if (errno == ENOSYS) break;     // not supported → fallback
            return -1;                      // other error
        }
        p      += n;
        buflen -= (size_t)n;
    }
    if (buflen == 0) return 0;              // all bytes filled
#endif

    // Fallback: read from /dev/urandom (cryptographically secure PRNG)
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;

    while (buflen > 0) {
        n = read(fd, p, buflen);
        if (n <= 0) { close(fd); return -1; }
        p      += n;
        buflen -= (size_t)n;
    }

    close(fd);
    return 0;
}

