/*
 * Securely fill a buffer with cryptographically strong random bytes.
 * Uses the OS CSPRNG (getrandom) and retries until the buffer is full.
 */
gboolean
secure_random_bytes(guint8 *buf, gsize len)
{
  gsize offset = 0;

  if (buf == NULL || len == 0)
    return FALSE;

  while (offset < len)
    {
      ssize_t rc = getrandom(buf + offset, len - offset, 0);

      if (rc < 0)
        {
          if (errno == EINTR)
            continue; /* retry on interrupt */

          msg_error("Failed to generate secure random bytes",
                    evt_tag_error("error"));
          return FALSE;
        }

      if (rc == 0)
        {
          msg_error("getrandom returned 0 bytes, aborting");
          return FALSE;
        }

      offset += (gsize) rc;
    }

  return TRUE;
}

