struct flow *flow_alloc(int nr_cpus)
{
    /* Basic sanity checks for pointer scaling assumptions */
    if (sizeof(struct flow_stats *) % sizeof(long) != 0) {
        fprintf(stderr, "Pointer size not aligned to long; aborting.\n");
        return NULL;
    }

    /* Allocate one block: flow + array of nr_cpus pointers */
    size_t extra = (size_t)nr_cpus * sizeof(struct flow_stats *);
    struct flow *f = malloc(sizeof(*f) + extra);
    if (!f) return NULL;

    /* cpu_stats points right after the base struct, at pointer-aligned offset */
    f->cpu_stats = (struct flow_stats **)(f + 1);

    /* Initialize pointer array safely using correct scaling */
    for (int i = 0; i < nr_cpus; i++)
        f->cpu_stats[i] = NULL;

    return f;
}

