struct reg_desc {
    uintptr_t base;   /* base address of register block */
    uint32_t  size;   /* access size in bytes: 1,2,4,8 */
};

uint64_t safe_reg_read(const struct reg_desc *table,
                       size_t table_len,
                       uintptr_t addr)
{
    const struct reg_desc *e = table;
    size_t remain = table_len;

    while (remain) {
        /* size must be power of two and <= 8 */
        if ((e->size & (e->size - 1)) == 0 && e->size <= 8) {
            uintptr_t aligned = addr & ~(uintptr_t)(e->size - 1);

            /* check that addr belongs to this entry and is aligned */
            if (aligned == e->base &&
                (addr & (e->size - 1)) == 0) {

                /* correct pointer scaling: cast to byte pointer,
                   then add byte offset, then cast back */
                volatile uint8_t  *p8  = (volatile uint8_t *)e->base;
                volatile void     *ptr = (void *)(p8 + 0); /* byte-wise */

                switch (e->size) {
                    case 1: return *(volatile uint8_t  *)ptr;
                    case 2: return *(volatile uint16_t *)ptr;
                    case 4: return *(volatile uint32_t *)ptr;
                    case 8: return *(volatile uint64_t *)ptr;
                }
            }
