/*
 * Secure pattern to avoid CWE-468 (Incorrect Pointer Scaling):
 * - Always convert typed pointers to uintptr_t before adding a byte offset.
 * - Do NOT do:   ptr = ptr + diff_bytes;   // scaled by sizeof(*ptr)
 * - Instead do:  ptr = (T*)( (uintptr_t)ptr + diff_bytes );
 */

void process_floats(
    const float* base,        // input buffer
    size_t       len_bytes,   // length in BYTES
    const int32_t* offsets,   // byte offsets between elements
    size_t       count,       // number of elements to visit
    float*       out)
{
  const float* p = base;
  size_t       remaining = len_bytes;

  for (size_t i = 0; i < count; i++) {
    if (remaining < sizeof(float)) {
      // prevent out-of-bounds access
      break;
    }

    float value = *p;          // safe access after bounds check
    out[i] = value;            // store result

    // diff is in BYTES; use uintptr_t to avoid incorrect scaling
    intptr_t diff = offsets[i];
    if ((diff < 0 && (size_t)(-diff) > (uintptr_t)p - (uintptr_t)base) ||
        (diff > 0 && (size_t)diff > remaining)) {
      // moving would go out of bounds; stop
      break;
    }

    p = (const float*)( (uintptr_t)p + (uintptr_t)diff );
    remaining = len_bytes - ((uintptr_t)p - (uintptr_t)base);
