function createSecureInviteLink(password, teamId, role) {
    if (!password || !password.trim()) {
        throw new Error('Password required');
    }

    role = role || 'VIEWER';

    // Create a random, typed hash for the invite (implementation uses strong randomness)
    const inviteHash = Hash.createRandomHash('invite', password);
    const hashData   = Hash.parseTypeHash('invite', inviteHash);

    // Derive independent seeds from the invite key (internal crypto-safe function)
    const seeds = InviteInner.deriveSeeds(hashData.key);

    // Derive a strong salt using app-wide loginSalt and user password
    const salt  = InviteInner.deriveSalt(password, AppConfig.loginSalt);

    // Use scrypt as a strong KDF to derive invite bytes (no MD5/SHA-1/weak ciphers)
    return new Promise((resolve, reject) => {
        InviteInner.deriveBytes(seeds.scrypt, salt, (derivedBytesBase64, err) => {
            if (err) {
                return reject(err);
            }

            const inviteLink = origin + '/teams/#' + inviteHash;

            module.execCommand('CREATE_INVITE_LINK', {
                teamId:  teamId,
                role:    role,
                hash:    inviteHash,
                seeds:   seeds,
                bytes64: derivedBytesBase64
            }, (result) => {
                if (result && result.error) {
                    return reject(new Error('Failed to create invite link'));
                }
                resolve(inviteLink); // securely generated invite URL
            });
        });
    });
}

