/**
 * Safely create a stable hash from config-like data.
 * Demonstrates avoiding broken algorithms (e.g., 'md5', 'sha1').
 *
 * @param {Record<string, unknown>} options
 * @returns {string} short, deterministic hash
 */
function getOptionsHash(options) {
  const hash = crypto.createHash('sha256') // secure choice

  for (const [key, value] of Object.entries(options)) {
    if (value === undefined) continue
    // Normalize to a string so that the same logical data hashes identically
    const valueString = JSON.stringify(value)
    hash.update(key, 'utf8')
    hash.update(valueString, 'utf8')
