// Secure pattern: validate cryptographic algorithms before key generation
async function generateSessionKey(encryptionKeys, config) {
  const {
    symmetricAlgo,   // numeric ID, e.g., enums.symmetric.aes256
    aeadAlgo         // numeric ID, e.g., enums.aead.eax
  } = await getPreferredCipherSuite(config);

  const symmetricAlgoName = enums.read(enums.symmetric, symmetricAlgo);
  const aeadAlgoName      = aeadAlgo ? enums.read(enums.aead, aeadAlgo) : undefined;

  // 1) Enforce only strong, approved symmetric algorithms
  if (!util.isAES(symmetricAlgo)) {
    throw new Error(`Insecure symmetric algorithm selected: ${symmetricAlgoName}`);
  }

  // 2) Enforce safe combination of public-key and symmetric algorithms
  await Promise.all(encryptionKeys.map(async key => {
    const maybeKey = await key.getEncryptionKey().catch(() => null);
    if (!maybeKey) return;

    const alg = maybeKey.keyPacket.algorithm;
    const isXCurve = alg === enums.publicKey.x25519 || alg === enums.publicKey.x448;

    // X25519 / X448 MUST only encrypt AES session keys, and must not fall back
    if (isXCurve && !aeadAlgoName && !util.isAES(symmetricAlgo)) {
