/**
 * @param {string} content   CSS content to be inlined
 * @param {object} opts
 * @param {boolean} opts.useHashes  true = use "sha256-..." sources, false = use nonces
 * @param {string}  opts.nonce     securely generated nonce (e.g., crypto.randomUUID())
 * @param {string[]} opts.styleSrcElemCsp  accumulated style-src-elem CSP values
 */
function addStyleWithCsp(content, { useHashes, nonce, styleSrcElemCsp }) {
  if (!content) return;

  /** @type {`nonce-${string}` | `sha256-${string}`} */
  const source = useHashes
    ? `sha256-${sha256(content)}` // SHA-256 is strong and CSP-recommended
    : `nonce-${nonce}`;          // nonce must be cryptographically random

  // Ensure Svelte’s empty comment hash is present to keep CSP intact
  const EMPTY_COMMENT_HASH =
    'sha256-9OlNO0DNEeaVzHL4RZwCLsBHA8WBQ8toBp/4F5XV2nc=';

  if (!styleSrcElemCsp.includes(EMPTY_COMMENT_HASH)) {
    styleSrcElemCsp.push(EMPTY_COMMENT_HASH);
