  if (source !== EMPTY_COMMENT_HASH && !styleSrcElemCsp.includes(source)) {
    styleSrcElemCsp.push(source);
  }

  // Now safely inject the style; browser will allow it due to CSP hash/nonce
  const style = document.createElement('style');
  style.textContent = content;
  document.head.appendChild(style);
}

