const argon2 = require('argon2');

// Hash a password before storing it (e.g., during user registration)
async function hashPassword(plainPassword) {
  // Argon2id is recommended for password hashing
  const hash = await argon2.hash(plainPassword, {
    type: argon2.argon2id, // avoids weak or deprecated algorithms
    timeCost: 3,           // CPU cost
    memoryCost: 1 << 15,   // RAM cost (e.g., 32 MB)
    parallelism: 1
  });
  return hash; // store this hash in your database, not the plain password
}

