import crypto from 'crypto';
import fetch from 'node-fetch';

// Securely call Facebook Graph API using a strong cryptographic algorithm (HMAC-SHA256)
async function getFacebookIdentity({ accessToken, appSecret, apiVersion = '20.0', fields = [] }) {
  if (!accessToken || !appSecret) {
    throw new Error('Missing access token or app secret');
  }

  // Use a modern, non-broken algorithm: HMAC-SHA256
  const hmac = crypto.createHmac('sha256', appSecret);
  hmac.update(accessToken);
  const appSecretProof = hmac.digest('hex');

  const url = new URL(`https://graph.facebook.com/v${apiVersion}/me`);
  url.searchParams.set('access_token', accessToken);
  url.searchParams.set('appsecret_proof', appSecretProof);
  if (fields.length) {
    url.searchParams.set('fields', fields.join(','));
  }

  const res = await fetch(url.toString(), { method: 'GET' });
  if (!res.ok) {
    throw new Error(`Failed to fetch identity from Facebook: ${res.status} ${res.statusText}`);
  }

  return res.json();
}

export { getFacebookIdentity };

