// Secure cryptographic algorithm selection to prevent CWE-327
// Only allow vetted, modern algorithms (AES-GCM / AES-CTR with strong keys)

const ALLOWED_CIPHER_ALGOS = Object.freeze([
  'aes-128-gcm',
  'aes-192-gcm',
  'aes-256-gcm',
  'aes-256-ctr'
]);

/**
 * Validate that the requested algorithm is explicitly whitelisted.
 * Rejects deprecated/weak algorithms (e.g., DES, 3DES, RC4, MD5-based).
 */
function isAllowedCipherAlgo(algo) {
  return ALLOWED_CIPHER_ALGOS.includes(String(algo).toLowerCase());
}

// Example usage with Node.js crypto
const crypto = require('crypto');

function encrypt(plaintext, key, algo = 'aes-256-gcm') {
  if (!isAllowedCipherAlgo(algo)) {
    throw new Error(`Disallowed cipher algorithm: ${algo}`);
  }

  const iv = crypto.randomBytes(12); // 96-bit IV recommended for GCM
  const cipher = crypto.createCipheriv(algo, key, iv);

  const ciphertext = Buffer.concat([
    cipher.update(plaintext, 'utf8'),
    cipher.final()
  ]);

  return { algo, iv, ciphertext, authTag: cipher.getAuthTag() };
}

