/**
 * SecureHasher only allows strong, vetted hash algorithms.
 * This prevents using weak/broken algorithms (e.g., MD5, SHA-1).
 */
class SecureHasher {
  /**
   * @param {"SHA-224"|"SHA-256"} algorithm - Allowed hash variant
   * @param {object} [options]
   * @param {{ value: string, format: string, encoding?: string }} [options.hmacKey]
   */
  constructor(algorithm, options = {}) {
    // Enforce a strict allow‑list of algorithms
    const allowed = new Set(["SHA-224", "SHA-256"]);
    if (!allowed.has(algorithm)) {
      throw new Error(`Unsupported hash algorithm: ${algorithm}`);
    }

    this.algorithm = algorithm;
    this.blockSize = 512;
    this.hashLength = algorithm === "SHA-224" ? 224 : 256;

    if (options.hmacKey) {
      this.hmacKey = this._normalizeHmacKey(options.hmacKey);
    }
  }

  _normalizeHmacKey(keySpec) {
    const msg = "hmacKey must include a value and format";
    if (!keySpec || keySpec.value === undefined || !keySpec.format) {
      throw new Error(msg);
    }

    const encoding = keySpec.encoding || "UTF8";
    // Stub: convert keySpec.value according to keySpec.format + encoding
    // In real code, map only trusted formats/encodings to a byte array.
    return this._encodeToBytes(keySpec.value, keySpec.format, encoding);
  }

  _encodeToBytes(value, format, encoding) {
    // Minimal, safe example using TextEncoder for UTF-8 strings
    if (format === "text" && encoding.toUpperCase() === "UTF8") {
      return new TextEncoder().encode(value);
    }
    throw new Error("Unsupported key format or encoding");
  }
}

