int get_user_email(sqlite3 *db, const char *user_id, char *outEmail, int outSize){
    const char *sql =
        "SELECT email FROM users WHERE user_id = ?1";  /* Placeholders, no string concat */
    sqlite3_stmt *stmt = NULL;
    int rc;

    /* Prepare the statement once with static SQL */
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if( rc != SQLITE_OK ) return rc;

    /* Bind untrusted input as data, not as SQL */
    rc = sqlite3_bind_text(stmt, 1, user_id, -1, SQLITE_TRANSIENT);
    if( rc != SQLITE_OK ){
        sqlite3_finalize(stmt);
        return rc;
    }

    /* Execute safely; user_id cannot change query structure */
    rc = sqlite3_step(stmt);
    if( rc == SQLITE_ROW ){
        const unsigned char *zEmail = sqlite3_column_text(stmt, 0);
        if( zEmail ) {
            sqlite3_snprintf(outSize, outEmail, "%s", zEmail);
            rc = SQLITE_OK;
        } else {
            rc = SQLITE_ERROR;
        }
    } else if( rc == SQLITE_DONE ){
        rc = SQLITE_NOTFOUND;  /* No such user */
    }

    sqlite3_finalize(stmt);
    return rc;
}

