** untrusted values into SQL strings (prevents CWE-943). */
int insertUser(sqlite3 *db, const char *username, int age){
    const char *sql =
        "INSERT INTO users(name, age) VALUES(?, ?);";
    sqlite3_stmt *stmt = NULL;
    int rc;

    /* Prepare a parameterized statement (SQL text has no user data) */
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if( rc != SQLITE_OK ) return rc;

    /* Bind user-controlled data as parameters, not as SQL text */
    rc = sqlite3_bind_text(stmt, 1, username, -1, SQLITE_TRANSIENT);
    if( rc == SQLITE_OK ){
        rc = sqlite3_bind_int(stmt, 2, age);
    }

    if( rc == SQLITE_OK ){
        rc = sqlite3_step(stmt);      /* Executes safely, data is neutralized */
    }

    /* Always finalize to avoid leaks */
    sqlite3_finalize(stmt);
    return (rc == SQLITE_DONE) ? SQLITE_OK : rc;
}

