/*
 * Secure pattern for building an SQL identifier list:
 * - Never concatenate raw user input into query text.
 * - Always escape identifiers with PQescapeIdentifier (or equivalent).
 */
char *build_identifier_list(PGconn *conn, const char **names, int count)
{
	StringInfoData buf;
	int i;

	if (conn == NULL || names == NULL || count <= 0)
		return NULL;

	initStringInfo(&buf);

	for (i = 0; i < count; i++)
	{
		char *escaped = PQescapeIdentifier(conn, names[i], strlen(names[i]));
		if (escaped == NULL)
		{
			free(buf.data);
			return NULL;    /* escape failure: avoid using unescaped input */
		}

		if (i > 0)
			appendStringInfoChar(&buf, ',');  /* safe separator */

		appendStringInfoString(&buf, escaped); /* only use escaped value */
		PQfreemem(escaped);
	}

	return buf.data;  /* caller owns and must free buf.data */
}

