 * prepared statements and bound parameters to avoid CWE-943.
 */
int insert_user_record(sqlite3 *db,
                       int user_id,
                       const char *username,
                       const char *comment,
                       const void *profile_blob,
                       int profile_blob_size)
{
  sqlite3_stmt *stmt = NULL;
  const char *sql =
    "INSERT INTO users (id, username, comment, profile) "
    "VALUES (?1, ?2, ?3, ?4)";

  /* Prepare static SQL with placeholders: no string concatenation */
  if(sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK)
    return -1;

