/*
 * Securely validate a domain pattern with optional wildcard '*'.
 * Rules:
 *  - At most one '*'
 *  - '*' must be a full-label wildcard: "*.example.com"
 *  - No partial wildcards like "foo*bar" or "*foo.com"
 *  - At least one dot after the wildcard
 */
int is_valid_domain_pattern(const char *pattern) {
    int star_pos = -1;
    int len = 0, dots_after_star = 0;
    int i;

    if (!pattern) return 0;

    /* Basic scan: count length, find '*', and ensure only legal chars */
    for (i = 0; pattern[i] != '\0'; i++) {
        char c = pattern[i];
        len++;

        if (c == '*') {
            if (star_pos != -1) return 0;            /* multiple '*' */
            star_pos = i;
        } else if (!( (c >= 'a' && c <= 'z') ||
                      (c >= 'A' && c <= 'Z') ||
                      (c >= '0' && c <= '9') ||
                      c == '.' || c == '-' )) {
            return 0;                                /* illegal char */
        }
    }
    if (len == 0) return 0;

    /* No wildcard: just ensure it has at least one dot */
    if (star_pos == -1) {
        for (i = 0; i < len; i++)
