#define FLAG_WRITE  0x02
#define FLAG_ADMIN  0x04

int process_request(unsigned int flags)
{
    unsigned int allowed_mask = FLAG_READ | FLAG_WRITE | FLAG_ADMIN;
    unsigned int unknown_bits;

    /* Reject any unknown / unexpected bits */
    unknown_bits = flags & ~allowed_mask;
    if (unknown_bits != 0) {
