 * by concatenating untrusted data (prevents CWE-943). */
int updateUserEmail(sqlite3 *db, int userId, const char *newEmail){
    const char *sql =
        "UPDATE users SET email = ?1 WHERE id = ?2;";   /* No user data in SQL */
    sqlite3_stmt *stmt = NULL;
    int rc;

    /* Prepare the statement once; SQL text is constant and not user‑constructed */
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if( rc != SQLITE_OK ) return rc;

    /* Bind user data as parameters (properly neutralized by SQLite) */
