    if( rc != SQLITE_OK ) goto done;

    /* Execute the query; data cannot break out of its parameter context */
    rc = sqlite3_step(stmt);
    if( rc == SQLITE_DONE ) rc = SQLITE_OK;

done:
    sqlite3_finalize(stmt);      /* Always finalize to avoid leaks */
    return rc;
}

