/*
 * Secure pattern against CWE-943:
 * - Never build query strings by concatenating raw user input.
 * - Instead, send data as separately encoded/length-prefixed fields.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Dummy “buffer” API to show the pattern */
struct buf {
    unsigned char *data;
    size_t len;
};

struct buf *buf_new(void);
int  buf_put_cstring(struct buf *b, const char *s);
void buf_free(struct buf *b);
void send_request(int channel, int msg_type, struct buf *b);

/* Secure wrapper that packages user input safely */
void send_auth_service(int channel, const char *service, const char *style)
{
    struct buf *b;
    int rc;

    b = buf_new();
    if (b == NULL) {
        fprintf(stderr, "buf_new failed\n");
        exit(1);
    }

    /* Each field is length-prefixed; no concatenated query text */
    rc = buf_put_cstring(b, service);
    if (rc == 0)
        rc = buf_put_cstring(b, style ? style : "");
    if (rc != 0) {
        fprintf(stderr, "assemble failed\n");
        buf_free(b);
        exit(1);
    }

    /* Downstream logic reads two separate fields, not a single query string */
    send_request(channel, /*MSG_AUTH_SERVICE*/ 1, b);

    buf_free(b);
}

