// Safely normalize a header value to prevent HTTP response/request splitting.
// - Removes CR/LF outright
// - Rejects control chars and non-printable/unusual Unicode range
// - Can be used before inserting user data into any HTTP header field
bool NormalizeHttpHeaderValue(std::wstring& value)
{
    // 1. Remove CR and LF to block header injection via new lines
    value.erase(std::remove(value.begin(), value.end(), L'\r'), value.end());
    value.erase(std::remove(value.begin(), value.end(), L'\n'), value.end());

    // 2. Allow only printable, reasonable characters in header value
    for (size_t i = 0; i < value.size(); ++i)
    {
        wchar_t ch = value[i];

        // Disallow other control chars and overly high code points
        if (ch < 0x20 || ch == 0x7F || ch >= static_cast<wchar_t>(0xFFF0))
        {
            value = value.substr(0, i);  // truncate at first invalid char
            break;
        }
    }

    // Optionally, reject empty or fully truncated values
    return !value.empty();
}

