// Secure handling of request headers to prevent HTTP response splitting (CWE-113)

void handleRequest(const HTTPMessage& req, HTTPTransaction::Handler& txn) {
  // Safely read a header that might be attacker-controlled (e.g., Host)
  auto host = req.getHeaders().getSingleOrEmpty("Host");

  // Reject any header value that contains CR or LF (prevents CRLF injection)
  auto hasCRLF = [](folly::StringPiece v) {
    return v.find('\r') != std::string::npos ||
           v.find('\n') != std::string::npos;
  };

  if (hasCRLF(host)) {
    // Do not forward or reflect the unsafe header.
    // Return a fixed error response instead.
    HTTPMessage resp;
    resp.setStatusCode(400);
    resp.setStatusMessage("Bad Request");
    resp.getHeaders().set("Content-Type", "text/plain");
    txn.sendHeaders(resp);
    txn.sendBody(folly::IOBuf::copyBuffer("Invalid header value"));
    txn.sendEOM();
    return;
  }

  // Normal path: safe header, can be used internally or logged
  // but still should not be blindly reflected into response headers.
  HTTPMessage resp;
  resp.setStatusCode(200);
  resp.setStatusMessage("OK");
  resp.getHeaders().set("Content-Type", "text/plain");
  txn.sendHeaders(resp);
  txn.sendBody(folly::IOBuf::copyBuffer("Hello"));
  txn.sendEOM();
}

