// Secure helper: escape CR/LF so they can’t terminate or inject HTTP headers.
//
// Use this on any untrusted value before putting it into an HTTP header.
// Example:  "X-User: " + escapeForHeader(untrustedInput)

#include <QString>

QString escapeForHeader(const QString &input)
{
    QString out;
    out.reserve(input.size());

    for (QChar c : input)
    {
        switch (c.unicode())
        {
        case '\r':  // Carriage Return
            out += "\\r";
            break;
        case '\n':  // Line Feed
            out += "\\n";
            break;
        default:
            out += c;   // keep all other characters as-is
            break;
        }
    }

    return out;
}

