#include <string>
#include <algorithm>
#include <boost/beast/core/detail/base64.hpp>

// Generate a value that is safe to place in HTTP headers
// (no CR or LF, URL-safe alphabet, no padding).
std::string makeHeaderSafeValue(const std::string& input)
{
    using boost::beast::detail::base64;

    // Base64-encode input
    std::string encoded;
    encoded.resize(base64::encoded_size(input.size()));
    base64::encode(&encoded[0], input.data(), input.size());

    // Convert to URL-safe alphabet: '+' -> '-', '/' -> '_'
    std::replace(encoded.begin(), encoded.end(), '+', '-');
    std::replace(encoded.begin(), encoded.end(), '/', '_');

    // Strip padding '='
    while (!encoded.empty() && encoded.back() == '=')
        encoded.pop_back();

    // At this point, encoded contains only [A-Za-z0-9-_],
    // so it cannot contain CR (\r) or LF (\n) and is safe for headers.
    return encoded;
}

