// Encrypts plaintext with ChaCha20-Poly1305 using a 256-bit key and random nonce.
// Demonstrates using a modern AEAD cipher with strong key size to avoid CWE-326.
func Encrypt(key, plaintext, ad []byte) (nonce, ciphertext []byte, err error) {
	aead, err := chacha20poly1305.New(key) // 256-bit key, strong cipher
	if err != nil {
		return nil, nil, err
	}

	nonce = make([]byte, chacha20poly1305.NonceSize)
	if _, err = rand.Read(nonce); err != nil { // cryptographically secure nonce
		return nil, nil, err
	}

	ciphertext = aead.Seal(nil, nonce, plaintext, ad)
	return nonce, ciphertext, nil
}

// Decrypts and authenticates ciphertext. Authentication failure results in error.
func Decrypt(key, nonce, ciphertext, ad []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}

	// Open verifies the Poly1305 tag; invalid data returns an error.
	plaintext, err := aead.Open(nil, nonce, ciphertext, ad)
	if err != nil {
		return nil, err
	}
	return plaintext, nil
}

