// NewSecureTLSConfig returns a TLS config that avoids weak / deprecated crypto
func NewSecureTLSConfig(
	certs []tls.Certificate,
	rootCAs *x509.CertPool,
	serverName string,
) (*tls.Config, error) {
	if rootCAs == nil {
		return nil, errors.New("root CA pool required")
	}
	if serverName == "" {
		return nil, errors.New("server name required")
	}

	return &tls.Config{
