// generateStrongKeyPair creates a 2048‑bit RSA key pair, which is considered
// a minimum secure key size for TLS and helps prevent CWE‑326 (Inadequate
// Encryption Strength). Using weaker keys (e.g., 1024‑bit) would be insecure.
func generateStrongKeyPair() (*rsa.PrivateKey, *x509.CertificateRequest, error) {
	// Use at least 2048 bits for RSA keys in new systems
	const keySize = 2048

	// Generate a cryptographically strong RSA private key
	priv, err := rsa.GenerateKey(rand.Reader, keySize)
	if err != nil {
