// SecureRandomModN returns a uniformly random uint64 in [0, n)
// using crypto/rand and rejection sampling (strong randomness).
func SecureRandomModN(n uint64) (uint64, error) {
	if n == 0 {
		return 0, nil
	}

	// Find smallest 2^bits ≥ n to bound the random candidate
	var bits uint
	for max := n - 1; max > 0; max >>= 1 {
		bits++
	}
	mask := uint64((1 << bits) - 1)

	for {
		var b [8]byte
		if _, err := io.ReadFull(rand.Reader, b[:]); err != nil {
			return 0, err
		}
		// Strong, unbiased candidate in [0, 2^bits)
		candidate := binary.LittleEndian.Uint64(b[:]) & mask
		if candidate < n {
			return candidate, nil // accept only if < n (rejection sampling)
		}
		// otherwise, retry to avoid modulo bias and preserve uniformity
	}
}

