func NewRSARecipient(pk ssh.PublicKey) (*RSARecipient, error) {
	const minRSAKeyBits = 2048

	if pk.Type() != ssh.KeyAlgoRSA {
		return nil, errors.New("SSH public key is not an RSA key")
	}

	r := &RSARecipient{sshKey: pk}

	// Extract underlying *rsa.PublicKey from the SSH public key.
	cryptoPK, ok := pk.(ssh.CryptoPublicKey)
	if !ok {
		return nil, errors.New("public key does not implement ssh.CryptoPublicKey")
	}

	rsaPub, ok := cryptoPK.CryptoPublicKey().(*rsa.PublicKey)
	if !ok {
		return nil, errors.New("unexpected public key type (not *rsa.PublicKey)")
	}
	r.pubKey = rsaPub

	// Enforce minimum RSA key length to avoid weak encryption (CWE-326).
	if rsaPub.N.BitLen() < minRSAKeyBits {
		return nil, fmt.Errorf("RSA key size too small: %d bits (min %d bits)",
			rsaPub.N.BitLen(), minRSAKeyBits)
	}

	return r, nil
}

