	}

	// 2. Create a minimal but valid CA certificate template.
	tpl := &x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject:      pkix.Name{CommonName: "Example CA"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(365 * 24 * time.Hour), // 1 year validity
		KeyUsage:     x509.KeyUsageCertSign | x509.KeyUsageCRLSign,
		// Limit to appropriate key usages; do not over-broaden.
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
		BasicConstraintsValid: true,
		IsCA:                  true,
	}

	// 3. Self-sign the CA certificate using the strong key.
	certDER, err := x509.CreateCertificate(rand.Reader, tpl, tpl, caKey.Public(), caKey)
