    mbedtls_x509write_csr csr;
    mbedtls_x509write_csr_init(&csr);

    // Attach existing keypair to CSR
    mbedtls_x509write_csr_set_key(&csr, key);

    // CWE-328 mitigation: DO NOT use MD5 or SHA-1; use SHA-256 or stronger
    ret = mbedtls_x509write_csr_set_md_alg(&csr, MBEDTLS_MD_SHA256);
