#include <openssl/hmac.h>

bool ComputeHmacSha256(const uint8_t * key, size_t key_len,
                       const uint8_t * msg, size_t msg_len,
                       uint8_t * out, size_t out_len)
{
    if (!key || !msg || !out || key_len == 0 || msg_len == 0)
        return false;
    if (out_len < 32) // 32 bytes = 256 bits
        return false;

    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!ctx) return false;

    bool ok = HMAC_Init_ex(ctx, key, static_cast<int>(key_len), EVP_sha256(), nullptr) == 1
           && HMAC_Update(ctx, msg, msg_len) == 1;

    unsigned int mac_len = 0;
    if (ok && HMAC_Final(ctx, out, &mac_len) == 1 && mac_len == 32)
        ok = true;
    else
