class HmacSha256 {
public:
    HmacSha256(const unsigned char* key, size_t keyLen) {
        ctx = HMAC_CTX_new();
        if (!ctx)
            throw std::runtime_error("Failed to create HMAC context");

        // Use a strong hash function: EVP_sha256()
