/* Simple neutralization helper for log output */
static void safe_log_string(const char *src, char *dst, size_t dst_size)
{
    size_t i, j = 0;
    if (!src || dst_size == 0) return;

    for (i = 0; src[i] != '\0' && j + 1 < dst_size; i++)
    {
        unsigned char c = (unsigned char)src[i];

        /* Neutralize characters that can break log structure */
        if (c == '\r' || c == '\n')
        {
            if (j + 4 < dst_size)
            {
