  const sigBaseString = `v0:${slackRequestTimestamp}:${requestBodyStr}`;

  // Compute HMAC SHA256 of the base string
  const sha256Hex = crypto
    .createHmac("sha256", slackSigningSecret)
    .update(sigBaseString, "utf8")
    .digest("hex");

