function verifyHmac(secret, signature, payload) {
  // Compute expected HMAC as raw bytes (Buffer)
  const expected = crypto
    .createHmac("sha256", secret)
    .update(payload, "utf8")
    .digest(); // no encoding → Buffer

  // Decode provided signature (must also be a Buffer)
  let provided;
