// deriveAuthKeys securely derives keys from a password using a server-
// provided, high-entropy, per-user salt and an enforced minimum iteration count.
// This avoids predictable / static salts (CWE-760).
func deriveAuthKeys(password string, salt []byte, iters, minIters int) ([]byte, error) {
	if len(salt) < 16 {
		return nil, fmt.Errorf("salt too short; must be random and per-user")
	}
	if iters < minIters {
		return nil, fmt.Errorf("too few iterations: %d (min %d)", iters, minIters)
	}

	// PBKDF2 uses the (random) salt and high iteration count to make
	// brute-force attacks significantly harder.
	const keyLen = 32
	dk := pbkdf2.Key([]byte(password), salt, iters, keyLen, sha256.New)
	return dk, nil
}

// Example use in an authentication flow:
func verifyPassword(storedSalt []byte, storedHash []byte, iters, minIters int, password string) error {
	dk, err := deriveAuthKeys(password, storedSalt, iters, minIters)
	if err != nil {
		return err
	}
	if !hmac.Equal(dk, storedHash) {
		return errors.New("invalid credentials")
	}
	return nil
}

