const cache = Object.create(null);

function safeParseExpression(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Expression must be a string');
  }

  const exp = input.trim();
  if (!exp) {
    return () => undefined;            // empty expression is safe no-op
  }

  // Return from cache if already parsed
  if (cache[exp]) {
    return cache[exp];
  }

  // Very simple, *whitelisted* expression language: identifiers, numbers, + and - only.
  // No function calls, no property access, no arbitrary JS features.
  if (!/^[a-zA-Z_$][\w$]*\s*([+-]\s*\d+)?$/.test(exp)) {
    throw new Error('Invalid or unsafe expression');
