// Secure MAC verification pattern (prevents CWE-347: Improper Verification of Cryptographic Signature)
#include <cstring>   // for size_t
#include <stdint.h>

// Constant-time comparison to avoid timing attacks
bool constant_time_equals(const uint8_t *a, const uint8_t *b, size_t len)
{
    uint8_t diff = 0;
    for (size_t i = 0; i < len; ++i)
    {
        diff |= (a[i] ^ b[i]);
    }
    return diff == 0;
}

// Hypothetical secure MAC function (e.g., HMAC-SHA256)
bool compute_mac(const uint8_t *key, size_t key_len,
                 const uint8_t *msg, size_t msg_len,
                 uint8_t *out_mac, size_t out_mac_len);

static constexpr size_t kMAC_Length = 32; // HMAC-SHA256 output size

bool verify_mac(const uint8_t *key, size_t key_len,
                const uint8_t *provided_mac, size_t provided_mac_len,
                const uint8_t *msg, size_t msg_len)
{
    // 1. Strict length check: reject unexpected MAC sizes
    if (provided_mac_len != kMAC_Length)
        return false;

    uint8_t expected_mac[kMAC_Length];

    // 2. Compute MAC over the message with the shared secret key
    if (!compute_mac(key, key_len, msg, msg_len, expected_mac, sizeof(expected_mac)))
        return false;

    // 3. Constant-time comparison of full MAC bytes
    return constant_time_equals(provided_mac, expected_mac, kMAC_Length);
}

