// value *before* using any decrypted data.

CHIP_ERROR SecureDecryptAndUse(
    const uint8_t * ct, size_t ctLen,         // ciphertext
    const uint8_t * aad, size_t aadLen,       // associated data
    const uint8_t * tag, size_t tagLen,       // authentication tag
    const uint8_t * key, size_t keyLen,       // symmetric key
    const uint8_t * nonce, size_t nonceLen)   // nonce / IV
