    size_t cursor = 0;
    ByteSpan nonce = payload.SubSpan(cursor, CHIP_CRYPTO_AEAD_NONCE_LENGTH_BYTES);
    cursor += nonce.size();

    size_t cipherLen = sizeof(CounterType) + GetAppDataSize(payload);
    ByteSpan ciphertext = payload.SubSpan(cursor, cipherLen);
    cursor += ciphertext.size();

    ByteSpan mic = payload.SubSpan(cursor, CHIP_CRYPTO_AEAD_MIC_LENGTH_BYTES);
    VerifyOrReturnError(cursor + mic.size() == payload.size(), CHIP_ERROR_INVALID_MESSAGE_LENGTH);

