// Verifies an ECDSA signature over a previously computed digest.
// Returns true only if the signature is valid; false if invalid;
// throws on any internal error (no silent failures).
bool verifySignature(
    const std::vector<unsigned char>& digest,
    const std::vector<unsigned char>& signature,
    EC_KEY* publicKey)
{
    if (!publicKey)
        throw std::invalid_argument("Public key must not be null");

    if (digest.empty() || signature.empty())
        throw std::invalid_argument("Digest and signature must not be empty");

    int ret = ECDSA_verify(
        0,
        digest.data(), static_cast<unsigned int>(digest.size()),
        signature.data(), static_cast<unsigned int>(signature.size()),
        publicKey);

    if (ret == 1)      // Signature is valid
        return true;
    else if (ret == 0) // Signature is invalid (verification failed cleanly)
        return false;

    // ret < 0: internal error, do not treat as valid or invalid
    unsigned long err = ERR_get_error();
    throw std::runtime_error(
        std::string("ECDSA_verify failed: ") +
        (err ? ERR_error_string(err, nullptr) : "unknown error"));
}

