//  - signature points to raw r||s bytes of known fixed size RAW_SIG_LEN
//  - RAW_SIG_LEN is even (half for r, half for s)
//  - msg points to the message bytes to be verified
bool verifyDsaSignature(
    EVP_PKEY *pubKey,
    const uint8_t *msg, size_t msgLen,
    const uint8_t *signature, size_t sigLen)
{
    if (!pubKey || !msg || !signature) return false;
    if (sigLen == 0 || (sigLen % 2) != 0) return false; // basic sanity

    // 1. Rebuild DSA_SIG from raw r||s
    size_t half = sigLen / 2;
    DSA_SIG *sig = DSA_SIG_new();
    if (!sig) return false;

