// Simple RAII wrapper for X509_STORE and X509
using X509StorePtr = std::unique_ptr<X509_STORE, decltype(&X509_STORE_free)>;
using X509Ptr      = std::unique_ptr<X509, decltype(&X509_free)>;
using X509StoreCtxPtr =
    std::unique_ptr<X509_STORE_CTX, decltype(&X509_STORE_CTX_free)>;

bool verifyCertificate(const char* caFilePath, const char* certFilePath) {
  // Load trusted CA store
  X509StorePtr store(X509_STORE_new(), X509_STORE_free);
  if (!store || X509_STORE_load_locations(store.get(), caFilePath, nullptr) != 1)
    throw std::runtime_error("Failed to load CA store");

  // Load certificate to verify
  FILE* certFile = fopen(certFilePath, "r");
  if (!certFile) throw std::runtime_error("Failed to open certificate file");
  X509Ptr cert(PEM_read_X509(certFile, nullptr, nullptr, nullptr), X509_free);
  fclose(certFile);
  if (!cert) throw std::runtime_error("Failed to read certificate");

  // Create and initialize verification context
  X509StoreCtxPtr ctx(X509_STORE_CTX_new(), X509_STORE_CTX_free);
  if (!ctx || X509_STORE_CTX_init(ctx.get(), store.get(), cert.get(), nullptr) != 1)
    throw std::runtime_error("Failed to init verification context");

  // Perform full certificate chain and signature verification
  int rc = X509_verify_cert(ctx.get());
  if (rc != 1) {
    // Verification failed: reject certificate instead of accepting it
    return false;
  }
  // Verification succeeded: trusted issuer and valid signature/chain
  return true;
}

