// Secure pattern: reject untrusted / self-signed certificates by verifying
// the full certificate chain against a trusted root store.

#include <stdexcept>
#include <vector>

// Pseudocode interfaces for clarity.
struct Certificate { /* ... */ };
struct VerificationParams {
  std::vector<Certificate> peerChain;  // leaf first, root last
};
enum class AlertDescription { unknown_ca };

class CertificateVerifier {
public:
  // Throws on failure; returns normally only if chain is trusted.
  void verify(const VerificationParams& params) {
    if (!isChainValidAndTrusted(params.peerChain)) {
      throwVerificationError(AlertDescription::unknown_ca);
    }
  }
private:
  bool isChainValidAndTrusted(const std::vector<Certificate>& chain) {
    // 1. Parse and validate each cert (signature, validity period, key usage).
    // 2. Build a chain from leaf to a known trusted root in the local trust store.
    // 3. Verify each signature in the chain using the issuer's public key.
    // 4. Ensure the root is explicitly trusted (not just self-signed).
    // Return false if any step fails (incl. self-signed leaf without trust).
    return /* result of full chain + trust validation */ false;
  }

  [[noreturn]] void throwVerificationError(AlertDescription alert) {
    // Map alert to error and throw (or close connection).
    throw std::runtime_error("certificate verification failed: unknown_ca");
  }
};

// Example usage: verify a self-signed / untrusted cert is rejected.
void verifyPeerCertificate(const Certificate& selfSignedCert) {
  CertificateVerifier verifier;
  VerificationParams params{ .peerChain = { selfSignedCert } };

  try {
    verifier.verify(params);
  } catch (const std::runtime_error&) {
    // Connection must be aborted; do NOT accept this certificate.
  }
}

