// Secure RSA-PSS signature verification using OpenSSL EVP API.
// Demonstrates: proper algorithm selection, padding, salt length, and error checks.
void verifyRsaPssSignature(
    folly::ByteRange message,
    folly::ByteRange signature,
    const folly::ssl::EvpPkeyUniquePtr& publicKey,
    int hashNid /* e.g. NID_sha256 */) {

  // 1. Select a concrete hash algorithm from its NID (must match the signer’s choice).
  const EVP_MD* md = EVP_get_digestbynid(hashNid);
  if (!md) {
    throw std::runtime_error("Unsupported hash algorithm");
  }

  // 2. Create and own the digest context.
  folly::ssl::EvpMdCtxUniquePtr mdCtx(EVP_MD_CTX_new());
  if (!mdCtx) {
    throw std::runtime_error("Could not allocate EVP_MD_CTX");
  }

  // 3. Initialize verification with the public key and hash.
  EVP_PKEY_CTX* pkeyCtx = nullptr;
  if (EVP_DigestVerifyInit(mdCtx.get(), &pkeyCtx, md, nullptr, publicKey.get()) != 1) {
    throw std::runtime_error("Could not initialize signature verification");
  }

  // 4. Enforce RSA-PSS padding and a deterministic salt length policy.
  if (EVP_PKEY_CTX_set_rsa_padding(pkeyCtx, RSA_PKCS1_PSS_PADDING) <= 0) {
    throw std::runtime_error("Could not set RSA-PSS padding");
  }
  // Use salt length equal to hash length (recommended for RSA-PSS).
  if (EVP_PKEY_CTX_set_rsa_pss_saltlen(pkeyCtx, EVP_MD_size(md)) <= 0) {
    throw std::runtime_error("Could not set RSA-PSS salt length");
  }

  // 5. Feed the exact message bytes that were signed.
  if (EVP_DigestVerifyUpdate(mdCtx.get(), message.data(), message.size()) != 1) {
    throw std::runtime_error("Could not update verification");
  }

  // 6. Verify that the signature matches; treat any non‑success as failure.
  if (EVP_DigestVerifyFinal(
          mdCtx.get(),
          const_cast<unsigned char*>(signature.data()),  // OpenSSL API quirk
          signature.size()) != 1) {
    throw std::runtime_error("Signature verification failed");
  }
}

