import unicodedata
from typing import Union, Any

def _normalize_string(value: str) -> str:
    """Unicode-normalize and lowercase a string for stable comparison."""
    return unicodedata.normalize("NFKC", value).casefold()

def get_unique_key(input_data: Union[dict, str]) -> str:
    """
    Generate a stable, unique key from input using a strong hash (SHA-256).

    - Dict:
        * Keys are case-sensitive.
        * String values are normalized + case-insensitive.
        * Dict is serialized to canonical JSON (sorted keys).
    - Str:
        * Normalized + case-insensitive string is used directly.
    """
    if isinstance(input_data, dict):
        processed: dict[str, Any] = {
            key: _normalize_string(val) if isinstance(val, str) else val
            for key, val in input_data.items()
        }
        canonical = json.dumps(processed, sort_keys=True, separators=(",", ":"))
    elif isinstance(input_data, str):
        canonical = _normalize_string(input_data)
    else:
        raise ValueError("input_data must be a dict or a str")

    # Use a strong cryptographic hash (SHA-256), not weak hashes like MD5/SHA-1
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

