def compute_directory_hash(
    directory: Path,
    skip_pattern: str | None = None,
) -> str:
    """
    Securely compute a directory hash using SHA-256 (strong hash function).
    Avoids weak hashes like MD5 or SHA-1 (CWE-328).
    """
    # Collect all files recursively
    all_paths = sorted(directory.rglob("*"))

    # Optionally skip files whose full path matches a pattern
    if skip_pattern:
        matcher = re.compile(skip_pattern)
        all_paths = [
            p for p in all_paths
            if not matcher.search(os.fspath(p.resolve()))
        ]

    hasher = hashlib.sha256()  # Strong cryptographic hash

    for path in all_paths:
        if path.is_file() and not path.name.startswith("."):
            # Stream file contents to avoid large memory usage
            with path.open("rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    hasher.update(chunk)

    return hasher.hexdigest()

