#include <aws/s3/S3Client.h>
#include <aws/s3/model/PutObjectRequest.h>

void UploadWithStrongKmsEncryption(
    Aws::S3::S3Client &s3_client,
    const Aws::String &bucket,
    const Aws::String &key,
    const Aws::String &kms_key_id      // e.g., "alias/production-key"
)
{
    Aws::S3::Model::PutObjectRequest request;
    request.SetBucket(bucket);
    request.SetKey(key);
    request.SetBody(Aws::MakeShared<Aws::StringStream>("UploadTag") << "sensitive data");

    // Enforce AWS KMS server-side encryption instead of weaker or no encryption
    request.SetServerSideEncryption(Aws::S3::Model::ServerSideEncryption::aws_kms);
    request.SetSSEKMSKeyId(kms_key_id);  // Use a managed CMK or alias, not a raw/weak key

    // Optional: use encryption context for additional integrity & access control
    Aws::Map<Aws::String, Aws::String> context;
    context["s3:arn"] = "arn:aws:s3:::" + bucket;
    request.SetSSEKMSEncryptionContext(Aws::Utils::Json::JsonValue(context).View().WriteCompact());

    auto outcome = s3_client.PutObject(request);
    if (!outcome.IsSuccess())
        throw std::runtime_error("Failed to upload with SSE-KMS: " +
                                 outcome.GetError().GetMessage());
}

