// Helper to create a securely-configured SSLContext
std::shared_ptr<folly::SSLContext> createSecureSSLContext(
    const std::string& certPath,
    const std::string& keyPath) {

    auto ctx = std::make_shared<folly::SSLContext>();

    // 1. Prefer strong TLS protocol versions only
    ctx->setOptions(SSL_OP_NO_SSLv2 |
                    SSL_OP_NO_SSLv3 |
                    SSL_OP_NO_TLSv1 |
                    SSL_OP_NO_TLSv1_1);  // Allow TLS 1.2+

    // 2. Enforce strong cipher suites and disable weak ones
    //    - Excludes:
    //        ADH  : Anonymous Diffie-Hellman (no authentication)
    //        LOW  : Low-strength ciphers (e.g., 40/56-bit)
    //        EXP  : Export-grade ciphers
    //        MD5  : Ciphers using MD5 (weak hash)
    //    - @STRENGTH: Sort by strength, preferring strongest
    ctx->ciphers("ALL:!ADH:!LOW:!EXP:!MD5:@STRENGTH");

    // 3. Load certificate and private key (not about strength,
    //    but required for a usable TLS context)
    ctx->loadCertificate(certPath.c_str());
    ctx->loadPrivateKey(keyPath.c_str());

    return ctx;
}

