// Demonstrates use of modern, strong primitives to avoid CWE-326 (Inadequate Encryption Strength).

#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>

bool DecryptData_AES256_CBC(const uint8_t* ciphertext, size_t ciphertextLen,
                            const std::string& fileName,
                            const uint8_t* masterKey, size_t masterKeyLen,
                            std::vector<uint8_t>& plaintextOut)
{
    // 1) Derive a per-file 256‑bit key and 128‑bit IV using SHA‑256 (or a KDF).
    uint8_t digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX shaCtx;
    SHA256_Init(&shaCtx);
    SHA256_Update(&shaCtx, masterKey, masterKeyLen);
    SHA256_Update(&shaCtx, fileName.data(), fileName.size());
    SHA256_Final(digest, &shaCtx);

    const uint8_t* aesKey = digest;              // first 32 bytes → 256‑bit key
    const uint8_t* aesIv  = digest + 32 - 16;    // last 16 bytes → 128‑bit IV

    // 2) Decrypt with AES‑256‑CBC using a vetted crypto library (OpenSSL EVP).
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return false;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, aesKey, aesIv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    plaintextOut.resize(ciphertextLen + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    int outLen1 = 0, outLen2 = 0;

    if (EVP_DecryptUpdate(ctx, plaintextOut.data(), &outLen1, ciphertext,
                          static_cast<int>(ciphertextLen)) != 1 ||
        EVP_DecryptFinal_ex(ctx, plaintextOut.data() + outLen1, &outLen2) != 1)
    {
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    EVP_CIPHER_CTX_free(ctx);
    plaintextOut.resize(outLen1 + outLen2);
    return true;
}

