#include <cstddef>
#include <cstdint>
using u8 = uint8_t;

struct Sha512Ctx  { /* opaque */ };
struct HmacSha512 {
    Sha512Ctx  sha;           // inner SHA-512 context
    u8         key_block[128]; // SHA-512 block size
};

// External strong primitives (well-vetted implementation, e.g., OpenSSL / libsodium)
void sha512_init   (Sha512Ctx *c);
void sha512_update (Sha512Ctx *c, const u8 *data, size_t len);
void sha512_final  (Sha512Ctx *c, u8 out[64]);
void sha512_hash   (u8 out[64], const u8 *data, size_t len);

// Initializes inner HMAC state securely (no truncated or home‑grown crypto)
void hmac_sha512_init(HmacSha512 *ctx, const u8 *key, size_t key_len)
{
    u8 key_hash[64]; // SHA-512 output size

    // 1) Reduce oversize key using SHA‑512 (per RFC 2104 / RFC 4868)
    if (key_len > sizeof(ctx->key_block)) {
        sha512_hash(key_hash, key, key_len);
        key     = key_hash;
        key_len = sizeof(key_hash);
    }

    // 2) Build inner padded key: (key || zeros) XOR 0x36, to full block size
    size_t i = 0;
    for (; i < key_len; ++i)
        ctx->key_block[i] = key[i] ^ 0x36;
    for (; i < sizeof(ctx->key_block); ++i)
        ctx->key_block[i] = 0x36;

    // 3) Initialize strong inner hash with full block
    sha512_init(&ctx->sha);
    sha512_update(&ctx->sha, ctx->key_block, sizeof(ctx->key_block));
}

