/*
 * Secure temporary file creation pattern (mitigates CWE-377)
 *
 * Key points:
 *  - Use mkdtemp() with XXXXXX to create a unique, private temp directory.
 *  - Build a filename template inside that directory containing XXXXXX.
 *  - Use mkostemps() (or mkstemp()) to open the file atomically.
 *  - Use O_CLOEXEC so the fd is not leaked across exec().
 *  - Remove the file and directory when done.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>

int main(void) {
    char dir_template[] = "/tmp/myapp-XXXXXX";
    char file_template[sizeof(dir_template) + 20];
    int  fd = -1;

    /* 1. Create a unique temporary directory securely */
    if (!mkdtemp(dir_template)) {
        perror("mkdtemp");
        return 1;
    }

    /* 2. Build file template inside that directory */
    snprintf(file_template, sizeof(file_template),
             "%s/tmpfile-XXXXXX", dir_template);

    /* 3. Create/open the temporary file atomically */
    fd = mkostemps(file_template, 0, O_CLOEXEC);
    if (fd < 0) {
        perror("mkostemps");
        rmdir(dir_template);
        return 1;
    }

    /* ... use fd safely (read/write) ... */

    /* 4. Cleanup: close, unlink file, remove directory */
    close(fd);
    unlink(file_template);
    rmdir(dir_template);
    return 0;
}

