/*
 * Secure temporary file creation on Windows:
 * - Uses a unique, randomized name.
 * - Uses CreateFileW with CREATE_NEW so creation is atomic.
 * - Fails if the file already exists (no TOCTOU window).
 */
#include <windows.h>
#include <io.h>
#include <fcntl.h>

int secure_tmpfile_w(const wchar_t* path, int* out_fd) {
  HANDLE hFile = CreateFileW(path,
                             GENERIC_READ | GENERIC_WRITE,
                             FILE_SHARE_READ,      /* optional: limit sharing */
                             NULL,
                             CREATE_NEW,           /* fail if file exists */
                             FILE_ATTRIBUTE_TEMPORARY |
                               FILE_FLAG_DELETE_ON_CLOSE,
                             NULL);
  if (hFile == INVALID_HANDLE_VALUE) {
    if (GetLastError() == ERROR_FILE_EXISTS) {
      /* Caller should generate a new random name and retry */
      return 0;  /* indicate "try another name" */
    }
    return -1;   /* other error */
  }

  int fd = _open_osfhandle((intptr_t)hFile, _O_RDWR);
  if (fd < 0) {
    CloseHandle(hFile);
    return -1;
  }

  *out_fd = fd;
  return 1;      /* success */
}

