/* Securely create a unique temporary file and return its path.
 * The file is created atomically to avoid race conditions (CWE-377). */
char *make_secure_temp_file(void)
{
    const char *tmpdir = getenv("TMPDIR");
    if (!tmpdir || !*tmpdir)
        tmpdir = "/tmp";

    const char *tmpl = "/myapp-XXXXXX";      // XXXXXX required by mkstemp
    size_t len = strlen(tmpdir) + strlen(tmpl) + 1;

    char *path = malloc(len);
    if (!path)
