    int fd = mkstemp(path);                  // atomic creation, unique name
    if (fd == -1) {
        free(path);
        return NULL;                         // handle error appropriately
    }

    if (close(fd) == -1) {                   // do not leak the descriptor
        unlink(path);
        free(path);
        return NULL;
    }

    return path;                             // caller owns path and file
}

