/*
 * Secure temporary file creation pattern (prevents CWE-377)
 *
 * Key points:
 * - Do NOT build temp filenames in world-writable dirs and then open them.
 * - Instead, use O_CREAT | O_EXCL to create the file atomically.
 * - Immediately lock the file to avoid concurrent use.
 */

#include <fcntl.h>
#include <errno.h>
#include <sys/file.h>
#include <unistd.h>
#include <stdio.h>

int create_secure_tmp(const char *dirfd_path, const char *name)
{
    int dfd = open(dirfd_path, O_DIRECTORY | O_RDONLY | O_CLOEXEC);
    if (dfd < 0) {
        perror("open dir");
        return -1;
    }

    /* Atomically create the temp/marker file; fail if it already exists. */
    int fd = openat(dfd, name, O_RDWR | O_CREAT | O_EXCL | O_CLOEXEC, 0600);
    if (fd < 0) {
        perror("openat temp");
        close(dfd);
        return -1;
    }

    /* Acquire an exclusive lock on the file. */
    struct flock lk = {0};
    lk.l_type   = F_WRLCK;
    lk.l_whence = SEEK_SET;

    if (fcntl(fd, F_OFD_SETLKW, &lk) < 0) {
        if (errno == EINVAL) {            /* Fallback if OFD locks unsupported */
            if (flock(fd, LOCK_EX) < 0) {
                perror("flock");
                close(fd);
                close(dfd);
                return -1;
            }
        } else {
            perror("fcntl");
            close(fd);
            close(dfd);
            return -1;
        }
    }

    close(dfd);
    return fd;   /* Caller owns a securely created, locked temp file. */
}

