/*
 * Secure temporary file creation (CWE-377 resistant)
 * - Uses O_TMPFILE when available (no name in filesystem)
 * - Falls back to mkstemp() + unlink() to avoid races
 */
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

int secure_tmpfile(const char *dir, int flags, mode_t mode)
{
#if defined(O_TMPFILE)
    /* Prefer nameless temporary file if the OS supports O_TMPFILE */
    int fd = open(dir, flags | O_TMPFILE | O_EXCL, mode);
    if (fd >= 0)
        return fd;
    /* If O_TMPFILE fails, fall through to mkstemp fallback */
#endif

    char template_buf[PATH_MAX];
    int dir_len = strlen(dir);

    /* Build "dir/securetmp_XXXXXX" template */
    if (snprintf(template_buf, sizeof(template_buf),
                 "%s/%s", dir, "securetmp_XXXXXX") >= (int)sizeof(template_buf))
        return -1;

    int fd = mkstemp(template_buf);
    if (fd < 0)
        return -1;

    /* Remove directory entry; file lives only via the descriptor */
    unlink(template_buf);

    /* Apply requested permissions explicitly */
    if (fchmod(fd, mode) < 0) {
        close(fd);
        return -1;
    }

    /* Caller can use 'fd' as a secure temporary file */
    return fd;
}

