/**
 * Convert a value to a safe integer within bounds.
 * Non-numeric or out-of-range values fall back to a default.
 */
function toSafeInt(value, defaultValue, { min, max }) {
  const n = Number.parseInt(value, 10);
  if (Number.isNaN(n)) return defaultValue;
  if (n < min || n > max) return defaultValue;
  return n;
