  const bookIds = rawBookIds
    .filter(id => typeof id === 'string')       // only strings
    .map(id => id.trim())                       // remove surrounding spaces
    .filter(id => id.length > 0);               // no empty strings

  if (!bookIds.length) {
    return res.status(400).json({ error: 'Invalid book IDs' });
