class SafeQueryHandler {
  constructor(inputElement, db) {
    // Only allow safe keyword characters: letters and hyphens.
    // This prevents special characters (', ", ;, --, etc.) from affecting query logic.
    this._safeKeywordRegExp = /^[a-zA-Z\-]+$/;

    // Optional: remove any quotes if they slip in (defense in depth).
    this._stripQuotesRegExp = /["']/g;

    this._inputElement = inputElement;
    this._db = db;

    this._inputElement.addEventListener("change", () => this._onUserInput());
  }

  _onUserInput() {
    let userInput = this._inputElement.value.trim();

    // Strip quotes as an extra safeguard.
    userInput = userInput.replace(this._stripQuotesRegExp, "");

    // Enforce whitelist: reject or handle invalid input safely.
    if (!this._safeKeywordRegExp.test(userInput)) {
      console.warn("Rejected unsafe input:", userInput);
      return;
    }

    // Use parameterized / prepared query instead of string concatenation.
    const query = "SELECT * FROM styles WHERE property_name = ?";
    this._db.execute(query, [userInput])  // driver escapes special elements
      .then(results => this._handleResults(results))
      .catch(err => console.error("Query failed:", err));
  }

  _handleResults(results) {
    // Safely process results...
    console.log("Safe results:", results);
  }
}

