// All user-provided data is passed as values/parameters, not used to build query logic.

TQuery BuildSecureInsert(
    const TableMeta& table,
    const std::vector<std::string>& inputColumns,
    const std::vector<Value>&   inputValues,   // user data
    TContext& ctx)
{
    // 1. Validate/whitelist any options that affect query logic
    const std::string onConflictMode = "abort"; // fixed or selected from a whitelist

    // 2. Build a structured/typed insert, no raw SQL strings are concatenated
    auto builder = InsertBuilder(ctx)
        .Table(table)                          // structured table meta
        .Columns(inputColumns)                 // column identifiers as a list
        .Values(inputValues)                   // user data as typed values/params
        .OnConflict(onConflictMode);           // controlled literal/enum, not user text

    // 3. Settings are added as structured options, not interpolated into a query string
    builder.AddSetting("Mode", "insert");      // fixed, not user-controlled

    return builder.Build();                    // returns a compiled/typed query object
}

