otError History::Process(Arg aArgs[])
{
    static constexpr Command kCommands[] = {
        CMD_ENTRY("ipaddr",     HandleIpAddr),
        CMD_ENTRY("neighbor",   HandleNeighbor),
        CMD_ENTRY("route",      HandleRoute),
        CMD_ENTRY("stats",      HandleStats),
    };

    static_assert(BinarySearch::IsSorted(kCommands), "kCommands must be sorted");

    if (aArgs[0].IsEmpty() || (aArgs[0] == "help"))
    {
        OutputCommandTable(kCommands);
        return aArgs[0].IsEmpty() ? OT_ERROR_INVALID_COMMAND : OT_ERROR_NONE;
    }

    const Command *cmd = BinarySearch::Find(aArgs[0].GetCString(), kCommands);
    VerifyOrExit(cmd != nullptr, OT_ERROR_INVALID_COMMAND);

