bool deleteFileRecord(QSqlDatabase &db, const QString &filename, bool recursively)
{
    if (!db.isOpen())
        return false;

    // 1) Delete the exact file record by surrogate key (phash)
    {
        QSqlQuery q(db);
        q.prepare(QStringLiteral("DELETE FROM metadata WHERE phash = ?"));
        const qint64 phash = getPHash(filename.toUtf8()); // derived value, not string‑concatenated
