// Secure pattern: escape identifiers, never interpolate values; use parameters instead.
std::string BuildSecureUpdateSQL(const std::string &tableName,
                                 const std::vector<std::string> &columnNames)
{
    // Start UPDATE and safely escape the table name (identifier)
    std::string sql = "UPDATE \"";
    sql += SQLEscapeName(tableName);   // Escapes quotes / special chars in identifier
    sql += "\" SET ";

    // For each column, append:  "escapedName" = ?
    for (size_t i = 0; i < columnNames.size(); ++i)
    {
        if (i > 0)
            sql += ", ";

        sql += "\"";
        sql += SQLEscapeName(columnNames[i]);  // Escape identifier only
        sql += "\" = ?";                       // Use parameter placeholder for value
    }

    // Caller is expected to bind the WHERE id value as a parameter too
    sql += " WHERE \"id\" = ?";

    return sql;  // Example: UPDATE "Users" SET "Name" = ?, "Age" = ? WHERE "id" = ?
}

