// Safely updates the "randomnumber" column for a given "id" row.
// Demonstrates using prepared statements and bound parameters to
// avoid CWE-943 (no string concatenation with user data).
bool updateRandomNumber(QSqlDatabase &db, int id, int randomNumber)
{
    // Never build SQL by concatenating values into the string.
    // Use parameter placeholders instead.
    QSqlQuery query(db);
    query.prepare(QStringLiteral(
        "UPDATE world "
        "SET randomnumber = :randomnumber "
        "WHERE id = :id"));

    // Bind values to named placeholders; special characters are
    // handled by the database driver and cannot break query logic.
    query.bindValue(QStringLiteral(":randomnumber"), randomNumber);
    query.bindValue(QStringLiteral(":id"),            id);

    // Execute the prepared statement
    return query.exec();
}

