// Secure pattern: refuse queries that use dynamic args across
// functions with incompatible argument layouts (CWE-943 mitigation).

bool has_incompatible_args(const std::vector<FuncInfo> &funcs)
{
  if (funcs.empty())
    return false;

  const auto &base = funcs.front().arg_types;
  for (const auto &f : funcs)
  {
    if (f.arg_types.size() != base.size())
      return true;
    for (size_t i = 0; i < base.size(); ++i)
      if (f.arg_types[i] != base[i])
        return true;
  }
  return false;
}

bool validate_query(const std::vector<FuncInfo> &funcs,
                    const std::string &probe_code)
{
  const bool uses_args =
      probe_code.find("args.") != std::string::npos ||
      probe_code.find("args->") != std::string::npos;

  // Secure check: if dynamic args are used with incompatible
  // function signatures, reject the query to avoid corrupting
  // or misinterpreting the underlying data/query logic.
  if (uses_args && has_incompatible_args(funcs))
    return false;

  return true;
}

