// Secure pattern: strictly validate / whitelist user-supplied query options
// to avoid injecting special query-control characters (CWE-943).

unsigned parseSortOptions(const std::string &userInput, bool &useDescending) {
    unsigned sortMask = 0;
    useDescending = false;

    for (char c : userInput) {
        switch (c) {
        case 'n': // sort by name
            sortMask |= 0x01;
            break;
        case 'd': // sort by date
            sortMask |= 0x02;
            break;
        case 's': // sort by size
            sortMask |= 0x04;
            break;
        case 'r': // reverse order
            useDescending = true;
            break;
        default:
            // Reject any unexpected character to avoid it affecting query logic
            return static_cast<unsigned>(-1); // signal invalid input
        }
    }

    return sortMask;
}

