import bcrypt from 'bcrypt';

/**
 * Hash a plaintext password using bcrypt.
 * - Automatically generates a cryptographically strong, random salt.
 * - Does NOT use usernames, user IDs, timestamps, or any predictable values as salt.
 */
export async function hashPassword(plainPassword) {
  // 10–14 is a common range; higher = slower but more secure.
  const saltRounds = 12;

  // genSalt() creates a random salt; no user-controlled / predictable salt used.
  const salt = await bcrypt.genSalt(saltRounds);
  const hash = await bcrypt.hash(plainPassword, salt);

  // Store only this hash string in the database (salt is embedded inside).
  return hash;
}

/**
 * Verify a plaintext password against a stored bcrypt hash.
 */
export async function verifyPassword(plainPassword, storedHash) {
  return bcrypt.compare(plainPassword, storedHash);
}

