const crypto = require('crypto');

/**
 * Hash a string with a random salt using a strong algorithm (e.g., sha256).
 * Returns both salt and hash so the value can be verified later.
 */
function hashWithRandomSalt(value) {
  if (typeof value !== 'string') {
    throw new TypeError('value must be a string');
  }

  // 16 bytes (128 bits) of cryptographically strong random salt
  const salt = crypto.randomBytes(16).toString('hex');

  // Use HMAC with the random salt as key (salt is not predictable)
  const hash = crypto
    .createHmac('sha256', salt)
    .update(value, 'utf8')
    .digest('hex');

  // Store salt and hash together (e.g., in DB) for later verification
  return { salt, hash };
}

/**
 * Verify a value against a stored salt + hash pair.
 */
function verifyHash(value, salt, expectedHash) {
  const hash = crypto
    .createHmac('sha256', salt)
    .update(value, 'utf8')
    .digest('hex');

  return crypto.timingSafeEqual(
    Buffer.from(hash, 'hex'),
    Buffer.from(expectedHash, 'hex')
  );
}

