async function hashPassword(password) {
  // 1. Generate a cryptographically secure random salt
  const saltBytes = new Uint8Array(16); // 128-bit salt
  if (window.crypto && window.crypto.getRandomValues) {
    window.crypto.getRandomValues(saltBytes);
  } else {
    throw new Error("Secure random generator not available");
  }

  // 2. Derive a strong key from password + salt (PBKDF2 + SHA-256)
  const enc = new TextEncoder();
  const passwordKey = await crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    "PBKDF2",
    false,
    ["deriveBits"]
  );

  const derivedBits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      hash: "SHA-256",
      salt: saltBytes,
      iterations: 100000, // tune per performance/security needs
    },
    passwordKey,
    256
  );

  // 3. Return both salt and hash (base64) for storage
  const saltB64 = btoa(String.fromCharCode(...saltBytes));
  const hashB64 = btoa(String.fromCharCode(...new Uint8Array(derivedBits)));
  return { salt: saltB64, hash: hashB64 };
}

