import bcrypt from "bcrypt";

/**
 * Securely hash a password using a modern password-hashing function.
 * 
 * Key point for CWE-760:
 *  - Do NOT create or pass your own predictable salt (e.g., username, user ID, constant).
 *  - Let the library generate a strong, random salt internally.
 */
export async function hashPassword(rawPassword) {
  const password = String(rawPassword || "");

  if (!password) {
    throw new Error("Password is required");
  }

  // Prefer Argon2 when available
  if (argon2) {
    // No explicit salt is provided here; argon2 generates a random salt.
    return await argon2.hash(password, {
      type: argon2.argon2id,
      timeCost: 3,
      memoryCost: 2 ** 16,
      parallelism: 1,
    });
  }

  // Fallback to bcrypt; again, bcrypt generates its own random salt internally.
  const rounds = 12;
  return await bcrypt.hash(password, rounds);
}

