// Convert a simple "LIKE" pattern to a safe RE2 regex:
//
//  - '%'  → ".*" (any sequence)
//  - '_'  → "."  (single char)
//  - escapeChar (if present) escapes next '%', '_', or itself
//  - All regex metacharacters are escaped so RE2 sees them literally
//
// Using RE2 (non‑backtracking) plus careful escaping avoids
// exponential regex behavior (CWE-1333).
std::string likePatternToSafeRe2(
    std::string_view pattern,
    char escapeChar,              // pass '\0' if no escape char
    bool& validPattern) {

  std::string regex;
  validPattern = true;
  regex.reserve(pattern.size() * 2);
  regex.push_back('^');

  bool escaped = false;
  for (char c : pattern) {
    if (escaped) {
      // Only these can be escaped meaningfully
      if (c != '%' && c != '_' && c != escapeChar) {
        validPattern = false;
      }
      escaped = false;
    } else if (escapeChar && c == escapeChar) {
      escaped = true;
      continue;
    }

    switch (c) {
      case '%': regex += ".*"; break;
      case '_': regex += ".";  break;
