// Simple, safe regex validator: allow only literals plus limited quantifiers.
// Disallows grouping, alternation, and other complex constructs that can
// cause catastrophic backtracking (CWE-1333).
bool IsSafeRegex(const char* pattern) {
  if (!pattern) return false;

  bool prev_can_repeat = false;  // true if ?,*,+ is allowed after previous char

  for (int i = 0; pattern[i] != '\0'; ++i) {
    char c = pattern[i];

    if (c == '\\') {                 // Escaped character: treat as literal.
      if (pattern[++i] == '\0')      // Trailing backslash is invalid.
        return false;
      prev_can_repeat = true;        // Escaped char can be repeated.
      continue;
    }

    // Disallow constructs that increase regex engine complexity.
    if (c == '(' || c == ')' || c == '|' || c == '[' || c == ']' ||
        c == '{' || c == '}' ) {
      return false;                  // No groups, alternation, classes, etc.
    }

    // Anchors are allowed only at edges to keep behavior simple.
    if ((c == '^' && i != 0) || (c == '$' && pattern[i + 1] != '\0'))
      return false;

    // Quantifiers must follow a repeatable token (no "?", "*", "+" first, etc.).
    if ((c == '?' || c == '*' || c == '+')) {
      if (!prev_can_repeat) return false;
      prev_can_repeat = false;
    } else {
      // Normal literal or anchor: may be followed by a quantifier.
      prev_can_repeat = (c != '^' && c != '$');
    }
  }

  return true;
}

