static String extractFixedPrefixFromRegularExpression(const String & regexp)
{
    if (regexp.size() <= 1 || regexp[0] != '^')
        return {};

    String fixed_prefix;
    const char * begin = regexp.data() + 1;
    const char * pos = begin;
    const char * end = regexp.data() + regexp.size();

    while (pos < end)
    {
        switch (*pos)
        {
            case '\0':
                pos = end;
            break;

            case '\\':
            {
                ++pos;
                if (pos == end)
                    break;

                switch (*pos)
                {
                    case '|':
                    case '(':
                    case ')':
                    case '^':
                    case '$':
                    case '.':
                    case '[':
                    case ']':
                    case '?':
                    case '*':
                    case '+':
                    case '\\':
                    case '{':
                    case '}':
                    case '-':
                        fixed_prefix += *pos;
                        ++pos;
                    break;
                    default:
                        /// all other escape sequences are not supported
                            pos = end;
                }

                break;
            }

            /// non-trivial cases
            case '|':
                fixed_prefix.clear();
            [[fallthrough]];
            case '(':
            case '[':
            case '^':
            case '$':
            case '.':
            case '+':
                pos = end;
            break;

            /// Quantifiers that allow a zero number of occurrences.
            case '{':
            case '?':
            case '*':
                if (!fixed_prefix.empty())
                    fixed_prefix.pop_back();

            pos = end;
            break;
            default:
                fixed_prefix += *pos;
            pos++;
            break;
        }
    }

    return fixed_prefix;
}

