// Secure pattern: extract a simple fixed prefix from a ^-anchored regex
// and use it as a cheap pre-filter before running the full regex.
// This avoids running complex / potentially vulnerable patterns on
// obviously non‑matching inputs, mitigating CWE‑1333 (catastrophic backtracking).

#include <regex>
#include <string>

static std::string extractFixedPrefix(const std::string &re) {
    if (re.size() <= 1 || re[0] != '^') return {};
    std::string prefix;
    for (size_t i = 1; i < re.size(); ++i) {
        char c = re[i];
        if (c == '\\') {                         // allow escaped literals
            if (++i >= re.size()) break;
            char e = re[i];
            switch (e) {
                case '|': case '(': case ')': case '^': case '$':
                case '.': case '[': case ']': case '?': case '*':
                case '+': case '\\': case '{': case '}': case '-':
                    prefix.push_back(e); break;
                default: return {};             // unknown escape: stop
            }
        } else if (c == '|' || c == '(' || c == '[' ||
                   c == '^' || c == '$' || c == '.' || c == '+') {
            break;                              // non‑literal construct
        } else if (c == '{' || c == '?' || c == '*') {
            if (!prefix.empty()) prefix.pop_back(); // zero‑occurrence quantifier
            break;
        } else {
            prefix.push_back(c);                // literal
        }
    }
    return prefix;
}

