QRegularExpression makeSafeRegex(const QString &userInput,
                                 Tools::RegexConvertOpts opts)
{
    QString pattern;

    // 1. Always start from a fully escaped literal pattern
    QString escaped = Tools::escapeRegex(userInput);

    // 2. Apply only *controlled* wildcard expansions on the escaped text
    if (opts & Tools::RegexConvertOpts::WILDCARD_SINGLE_MATCH) {
        // Treat '?' in user input as single-char wildcard, but keep rest escaped
        escaped.replace("\\?", ".");  // replace the escaped '?' only
    }
    if (opts & Tools::RegexConvertOpts::WILDCARD_UNLIMITED_MATCH) {
        // Treat '*' in user input as limited wildcard, avoid nested/greedy patterns
        escaped.replace("\\*", ".{0,32}");  // bounded repetition to prevent blow‑ups
    }

    pattern = escaped;

    // 3. Optional exact match wrapper – no unescaped user fragments added
    if (opts & Tools::RegexConvertOpts::EXACT_MATCH) {
        pattern = "^(?:" + pattern + ")$";
    }

    // 4. Compile with safe options (no backtracking-heavy features enabled)
    QRegularExpression::PatternOptions reOpts = QRegularExpression::NoPatternOption;
    QRegularExpression re(pattern, reOpts);

    // Fail closed: if pattern is invalid, fall back to a safe literal match
    if (!re.isValid()) {
        re = QRegularExpression(QRegularExpression::escape(userInput));
    }
    return re;
}

