def abort_relocation(request: HttpRequest, relocation_uuid: str) -> JsonResponse:
    """
    Securely abort a relocation identified by UUID.

    Uses ORM parameter binding instead of building raw SQL strings, so any
    special characters in relocation_uuid are treated as data and cannot
    change the query logic (prevents CWE-943).
