/*
 * Secure key wrapping example:
 * - Uses an AES key-wrap algorithm (EVP_CIPH_WRAP_MODE),
 *   which does not rely on a CBC IV and therefore avoids
 *   CWE-329 (predictable IV in CBC mode).
 */
int secure_key_wrap(const unsigned char *kek, int kek_len,
                    const unsigned char *in, size_t in_len,
                    unsigned char *out, size_t *out_len)
{
    int ret = 0;
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *wrap_cipher = NULL;

    if (kek_len == 16)
        wrap_cipher = EVP_aes_128_wrap();
    else if (kek_len == 24)
        wrap_cipher = EVP_aes_192_wrap();
    else if (kek_len == 32)
        wrap_cipher = EVP_aes_256_wrap();
    else
        return 0; /* Invalid KEK size */

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL)
        return 0;

    /* No IV is supplied for key-wrap algorithms (not CBC mode). */
    if (EVP_EncryptInit_ex(ctx, wrap_cipher, NULL, kek, NULL) != 1)
        goto end;

    if (EVP_EncryptUpdate(ctx, out, (int *)out_len, in, (int)in_len) != 1)
        goto end;

    ret = 1; /* success */

end:
    EVP_CIPHER_CTX_free(ctx);
    return ret;
}

