int encrypt_with_random_iv(const EVP_CIPHER *cipher,
                           const unsigned char *plaintext, int plaintext_len,
                           const unsigned char *key, /* already random & secret */
                           unsigned char *iv,        /* out: random IV */
                           unsigned char *ciphertext)
{
