    int len = 0, ciphertext_len = 0;
    int iv_len = EVP_CIPHER_iv_length(cipher);

    if (iv_len <= 0)      /* CBC requires a non‑zero IV length */
        return -1;

    /* 1) Generate a fresh, unpredictable IV for this encryption */
    if (RAND_bytes(iv, iv_len) <= 0)
        return -1;

