# ---- Secure crypto helpers (avoid MD5/SHA1, use bcrypt/Argon2, etc.) ----

def generate_salt() -> bytes:
    # bcrypt.gensalt() generates a random salt with a strong work factor
    return bcrypt.gensalt(rounds=12)

def create_bcrypt_hash(plain_password: str, salt: bytes) -> bytes:
    # bcrypt.hashpw uses a slow, salted hash resistant to brute force
    return bcrypt.hashpw(plain_password.encode("utf-8"), salt)

