        if ((err = fw.open(key_url)) != srs_success) {
            return srs_error_wrap(err, "open file %s", key_url.c_str());
        }

        err = fw.write(key_, 16, NULL);
        fw.close();

        if (err != srs_success) {
            return srs_error_wrap(err, "write key");
        }
    }

    if (hls_keys_) {
        current_->config_cipher(key_, iv_);
