#include <sys/random.h>
#include <stdexcept>

bool GetSecureRandom(void *buffer, size_t length) {
    if (!buffer || length == 0)
        return false;

#if defined(SYS_getrandom) || defined(__linux__)
    // Prefer getrandom() when available (no need to open /dev/urandom).
    ssize_t res = getrandom(buffer, length, 0);
    if (res == static_cast<ssize_t>(length))
        return true;
