/*
 * Secure pattern against CWE-113 (HTTP Request/Response Splitting):
 * - Never copy untrusted strings directly into HTTP headers.
 * - Only use validated / sanitized values when building headers.
 */

#include <ctype.h>
#include <string.h>

#define MAX_HEADER_VALUE 128

/* Simple validator: reject any CR/LF or control characters */
int is_safe_header_value(const char *v) {
    for (; *v; v++) {
        unsigned char c = (unsigned char)*v;
        if (c < 0x20 || c == 0x7F) { /* control chars incl. \r(0x0D), \n(0x0A) */
            return 0;
        }
    }
    return 1;
}

/* Example: safely set a custom header from (potentially) untrusted input */
void set_safe_header(ne_request *req, const char *user_value) {
    char safe_value[MAX_HEADER_VALUE];

    if (!user_value || !is_safe_header_value(user_value)) {
        /* Fallback to a known-safe constant if input is missing/invalid */
        ne_add_request_header(req, "X-Custom", "default");
        return;
    }

    /* Truncate to a safe length; still contains only validated characters */
    strncpy(safe_value, user_value, sizeof(safe_value) - 1);
    safe_value[sizeof(safe_value) - 1] = '\0';

    ne_add_request_header(req, "X-Custom", safe_value);
}

