/* Safely append a header field/value pair to an HTTP-like header buffer.
 * User-controlled values are:
 *   - serialized with gst_value_serialize()
 *   - sanitized/escaped with g_strescape() to neutralize CR/LF and other
 *     control characters before being placed in the header.
 */
static gboolean
safe_append_header (const gchar *field_name, const GValue *value, GString *buf)
{
  gchar *value_str = gst_value_serialize (value);
  gchar *esc_value_str;

  if (value_str == NULL) {
    g_string_append_printf (buf, "%s: %s\n", field_name, "NULL");
    return TRUE;
  }

  /* Escape control characters so CR/LF cannot terminate the header early */
  esc_value_str = g_strescape (value_str, NULL);

  /* Use a single, controlled newline; never copy raw CR/LF from input */
  g_string_append_printf (buf, "%s: %s\n", field_name, esc_value_str);

  g_free (value_str);
  g_free (esc_value_str);
  return TRUE;
}

