static int handle_upgrade(request_rec *r)
{
    const char *upgrade  = apr_table_get(r->headers_in, "Upgrade");
    const char *conn     = apr_table_get(r->headers_in, "Connection");
    apr_array_header_t *offers = NULL;
    const char *err, *protocol;
    conn_rec *c = r->connection;

    /* Only proceed if client explicitly requests upgrade */
    if (!upgrade || !*upgrade || !conn ||
        !ap_find_token(r->pool, conn, "upgrade")) {
        return DECLINED;
    }

    /* Strictly parse the Upgrade header: rejects malformed / injected values */
    err = ap_parse_token_list_strict(r->pool, upgrade, &offers, 0);
    if (err || !offers || offers->nelts == 0) {
        ap_log_rerror(APLOG_MARK, APLOG_DEBUG, 0, r,
