    for(i = 0; i < in_len && pos + 2 < out_size; i++) {
        /* Optionally, you could only encode non-printables, but here
           we hex-encode everything for simplicity and safety. */
        pos += snprintf(&out[pos], out_size - pos, "%02X", in[i]);
