import fs from "fs";
import Ajv from "ajv";
import { CONFIG_SCHEMA } from "./schemas.js";  // trusted JSON Schema

const CONFIG_PATH = "./config.json";
const DEFAULT_CONFIG = Object.freeze({
  _version: "1.0.0",
  featureFlag: false,
  timeoutMs: 5000
});

// Safely load and validate configuration from untrusted JSON file
export function loadConfig() {
  if (!fs.existsSync(CONFIG_PATH)) {
    return { ...DEFAULT_CONFIG };
  }

  const raw = fs.readFileSync(CONFIG_PATH, "utf8");

  let parsed;
  try {
    // Use JSON.parse (no functions / prototypes), not eval or custom deserializer
    parsed = JSON.parse(raw);
  } catch {
    // Invalid JSON → treat as untrusted and fall back to safe defaults
    return { ...DEFAULT_CONFIG };
  }

  const ajv = new Ajv({ removeAdditional: true, allErrors: true });
  const validate = ajv.compile(CONFIG_SCHEMA);

  if (!validate(parsed)) {
    // Schema validation failed → prevent untrusted structure from being used
    console.error("Invalid config:", validate.errors);
    return { ...DEFAULT_CONFIG };
  }

  // Only validated, plain-data config is used by the application
  return { ...DEFAULT_CONFIG, ...parsed };
}

