func encryptAES(key []byte, plaintext []byte) ([]byte, error) {
	// AES-256 requires a 32-byte key; caller must supply a strong, random key.
	if len(key) != 32 {
		return nil, fmt.Errorf("key must be 32 bytes")
	}
	if len(plaintext) == 0 {
		return nil, nil
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

