def execute_bytecode(bytecode, context):
    """
    Securely execute limited bytecode; only allow calls to whitelisted functions.
    Bytecode format (simplified):
      ["PUSH_CONST", value]       -> push value on stack
      ["CALL_GLOBAL", name, n]    -> call allowed global function with n args
    """
    stack = []
    pc = 0

    while pc < len(bytecode):
        op = bytecode[pc]

        if op == "PUSH_CONST":
            _, value = bytecode[pc:pc+2]
            stack.append(value)
            pc += 2

        elif op == "CALL_GLOBAL":
            _, func_name, argc = bytecode[pc:pc+3]

            # Enforce strict whitelist: reject any unknown function
            if func_name not in ALLOWED_FUNCTIONS:
                raise BytecodeExecutionError(f"Unsupported function call: {func_name}")

            if len(stack) < argc:
                raise BytecodeExecutionError("Stack underflow")

            args = [stack.pop() for _ in range(argc)][::-1]
            result = ALLOWED_FUNCTIONS[func_name](*args)
            stack.append(result)
            pc += 3

        else:
            raise BytecodeExecutionError(f"Invalid opcode: {op}")

    if len(stack) != 1:
        raise BytecodeExecutionError("Invalid bytecode. More than one value left on stack")

    return stack[0]

