import http.client
from http import HTTPStatus

class SafeResponse:
    """
    Minimal example of strict header handling to prevent
    HTTP response splitting (CWE-113).
    """
    def __init__(self, status: int = HTTPStatus.OK):
        self.status = status
        self.headers = {}

    def add_header(self, name: str, value: str) -> None:
        # Reject any CR/LF or control characters in header name/value
        illegal = ['\r', '\n']
        if any(c in name for c in illegal) or any(c in value for c in illegal):
            raise ValueError("Invalid header: CR/LF not allowed")

        if any(ord(c) < 0x20 and c not in ('\t',) for c in value):
            raise ValueError("Invalid header: control characters not allowed")

        self.headers[name] = value

    def to_bytes(self) -> bytes:
        # Safely build HTTP response with validated headers
        lines = [f"HTTP/1.1 {self.status} {HTTPStatus(self.status).phrase}"]
        for k, v in self.headers.items():
            lines.append(f"{k}: {v}")
        lines.append("")  # end of headers
        lines.append("")  # end of response head
        return "\r\n".join(lines).encode("ascii")

