/*
 * Secure PBKDF2 usage:
 *  - Enforce MIN_SALT_LEN to avoid short / predictable salts
 *  - Enforce MIN_ITER to avoid fast, brute‑forceable hashes
 */
#define MIN_SALT_LEN 16      /* bytes */
#define MIN_ITER     100000  /* example minimum */

int derive_key_pbkdf2(const unsigned char *password, size_t pass_len,
                      const unsigned char *salt, size_t salt_len,
                      int iterations,
                      unsigned char *out_key, size_t out_key_len)
{
    /* Enforce lower bounds to avoid CWE‑760 (predictable / weak salt usage) */
    if (salt == NULL || salt_len < MIN_SALT_LEN) {
        /* Salt is too short, likely weak or predictable */
        ERR_raise(ERR_LIB_EVP, EVP_R_INVALID_SALT_LENGTH);
        return 0;
    }
    if (iterations < MIN_ITER) {
        /* Too few iterations makes brute forcing easier */
        ERR_raise(ERR_LIB_EVP, EVP_R_UNSUPPORTED_NUMBER_OF_ROUNDS);
        return 0;
    }

