                       const uint8_t *salt, size_t salt_len,
                       uint32_t iter, uint8_t *out, size_t out_len);

#define KEY_LEN       32          /* 256‑bit key              */
#define SALT_LEN      16          /* 128‑bit random salt      */
#define PBKDF2_ITER   100000      /* Slow enough to resist brute force */

typedef struct {
    uint8_t enc_key[KEY_LEN];
    uint8_t hmac_key[KEY_LEN];
    uint8_t salt[SALT_LEN];
    uint8_t hmac_salt[SALT_LEN];
} key_context;

/* Derive independent encryption and HMAC keys securely (no predictable salt). */
int derive_keys_from_password(const uint8_t *password, size_t pass_len,
                              key_context *ctx)
{
    /* 1. Generate a cryptographically strong, per‑context random salt */
    if (secure_random_bytes(ctx->salt, SALT_LEN) != 0)
        return -1;

    /* 2. Derive encryption key with PBKDF2 using the random salt */
    if (pbkdf2_hmac_sha256(password, pass_len,
                           ctx->salt, SALT_LEN,
                           PBKDF2_ITER, ctx->enc_key, KEY_LEN) != 0)
        return -1;

    /* 3. Derive a distinct HMAC salt from the encryption salt */
    memcpy(ctx->hmac_salt, ctx->salt, SALT_LEN);
    for (size_t i = 0; i < SALT_LEN; i++)
        ctx->hmac_salt[i] ^= 0x5A;    /* fixed public mask, still non‑identical salt */

    /* 4. Derive HMAC key using a different salt (and optionally different iter) */
    if (pbkdf2_hmac_sha256(ctx->enc_key, KEY_LEN,
                           ctx->hmac_salt, SALT_LEN,
                           PBKDF2_ITER / 2, ctx->hmac_key, KEY_LEN) != 0)
        return -1;

    return 0;
}

