function network_generate_salt()
{
	let salt = readfile("/dev/urandom", 16);
	if (length(salt) != 16)
		return;
	salt = map(split(salt, ""), (v) => ord(v));
	salt = join("", map(salt, (v) => sprintf("%02x", v)));
	return salt;
}

