#include <string.h>
#include <unistd.h>
#include <crypt.h>

// Secure password hashing with an unpredictable salt (avoids CWE-760).
int store_hashed_password(const char *username, const char *password, FILE *fp)
{
    unsigned char rand_buf[6];   // 6 random bytes -> 8 base64 chars
    char salt[32] = "$1$";       // use MD5-crypt as example: "$1$<8-chars>$"
    char *hash;
    int i;

    /* Get strong randomness for salt */
    FILE *urand = fopen("/dev/urandom", "rb");
    if (!urand || fread(rand_buf, 1, sizeof(rand_buf), urand) != sizeof(rand_buf)) {
        if (urand) fclose(urand);
        return -1;
    }
    fclose(urand);

    /* Base64-encode 6 random bytes into 8 printable chars */
    static const char b64[] =
        "./0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    for (i = 0; i < 8; i++) {
        salt[3 + i] = b64[rand_buf[i % 6] & 0x3f];
    }
    salt[3 + 8] = '\0';

    /* Compute salted hash; crypt() will interpret "salt" as salt spec */
    hash = crypt(password, salt);
    if (!hash)
        return -1;

    /* Store username and salted hash; hash string embeds the salt */
    if (fprintf(fp, "%s:%s\n", username, hash) < 0)
        return -1;

    return 0;
}

