/*
 * Secure hashing with an unpredictable salt to prevent CWE-760
 * - Uses /dev/urandom for salt (unpredictable)
 * - Uses a strong hash (SHA-256 via OpenSSL EVP API)
 */

#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>

#define SALT_LEN 16  /* 128-bit salt */

int get_random_bytes(unsigned char *buf, size_t len) {
    FILE *f = fopen("/dev/urandom", "rb");
    if (!f) return -1;
    size_t rc = fread(buf, 1, len, f);
    fclose(f);
    return (rc == len) ? 0 : -1;
}

int hash_with_salt(const char *password,
                   unsigned char *salt, size_t salt_len,
                   unsigned char *out, unsigned int *out_len) {
    if (get_random_bytes(salt, salt_len) != 0) return -1;  // unpredictable salt

    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!ctx) return -1;

    if (EVP_DigestInit_ex(ctx, EVP_sha256(), NULL) != 1 ||
        EVP_DigestUpdate(ctx, salt, salt_len) != 1 ||   // prepend salt
        EVP_DigestUpdate(ctx, password, strlen(password)) != 1 ||
        EVP_DigestFinal_ex(ctx, out, out_len) != 1) {
        EVP_MD_CTX_free(ctx);
        return -1;
    }
    EVP_MD_CTX_free(ctx);
    return 0;
}

