#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

#define SALT_LEN 16            /* At least 16 bytes is recommended */
#define KEY_LEN  32            /* 256-bit derived key */
#define PBKDF2_ITERATIONS 100000

/* Derive a key using PBKDF2 with a cryptographically strong, random salt. */
int derive_key_secure(const char *password,
                      unsigned char out_key[KEY_LEN],
                      unsigned char out_salt[SALT_LEN])
{
    /* 1) Generate an unpredictable salt with a CSPRNG */
    if (RAND_bytes(out_salt, SALT_LEN) != 1) {
        return 0; /* random generation failed */
    }

    /* 2) Use PBKDF2 with the random salt */
    if (PKCS5_PBKDF2_HMAC(
            password,
            (int)strlen(password),
            out_salt,
            SALT_LEN,
            PBKDF2_ITERATIONS,
            EVP_sha256(),
            KEY_LEN,
            out_key) != 1) {
        return 0; /* key derivation failed */
    }

    return 1; /* success: out_key and out_salt are securely set */
}

