// IsSSEKMSEncrypted securely distinguishes strong SSE-KMS from weaker/other modes.
// It only returns true when the algorithm is explicitly "aws:kms".
func IsSSEKMSEncrypted(meta map[string][]byte) bool {
	const (
		hdrSSEAlg  = "x-amz-server-side-encryption"
		hdrEncKey  = "x-amz-encrypted-key"
		valSSEKMS  = "aws:kms"
		valAES256  = "AES256" // SSE-S3 / SSE-C; not treated as KMS
	)

	algRaw, hasAlg := meta[hdrSSEAlg]
	if !hasAlg {
		return false
	}

	alg := string(algRaw)
	switch alg {
	case valSSEKMS:
		// Optional: require that an encrypted data key is present for KMS
		_, hasEncKey := meta[hdrEncKey]
		return hasEncKey
	case valAES256:
		// Explicitly *not* treated as KMS; avoids assuming weaker/legacy AES256
		// (e.g., SSE-C with user-managed keys) is equivalent to KMS-managed crypto.
		return false
	default:
		// Any unknown or legacy/weak algorithm is rejected rather than silently accepted.
		return false
	}
}

