func decryptKeySecure(
	privKey *ecdsa.PrivateKey,
	pubKey  *ecdsa.PublicKey,
	alg     string,          // "ECDH-ES", "ECDH-ES+A256KW", etc.
	enc     string,          // e.g. "A256GCM"
	apu, apv []byte,         // optional party info for KDF
	wrappedKey []byte,       // CEK if using key wrapping
) ([]byte, error) {

