// Securely validate allowed server-side encryption algorithms to avoid CWE-327.
package main

import (
	"encoding/xml"
	"errors"
)

type sseConfig struct {
	XMLName xml.Name `xml:"ServerSideEncryptionConfiguration"`
	Rule    struct {
		Default struct {
			Algorithm string `xml:"SSEAlgorithm"`
			KMSKeyID  string `xml:"KMSMasterKeyID"`
		} `xml:"ApplyServerSideEncryptionByDefault"`
	} `xml:"Rule"`
}

// encryptionConfigFromXMLBytes parses XML and rejects unsupported / risky algorithms.
func encryptionConfigFromXMLBytes(data []byte) (*sseConfig, error) {
	var cfg sseConfig
	if err := xml.Unmarshal(data, &cfg); err != nil {
		return nil, err
	}

