#include <stdexcept>
#include <string>
#include <set>

class SSLContext {
 public:
  // Only allow modern, strong signature algorithms
  void setSigAlgsOrThrow(const std::string& sigAlgs) {
    static const std::set<std::string> kAllowed = {
        "rsa_pss_rsae_sha256",
        "rsa_pss_rsae_sha384",
        "rsa_pss_rsae_sha512",
        "ECDSA+SHA256",
        "ECDSA+SHA384",
        "ECDSA+SHA512",
    };

    if (sigAlgs.empty()) {
      throw std::runtime_error("Signature algorithms list must not be empty");
    }

    // Split on ':' and validate each algorithm against allow‑list
    size_t start = 0;
    while (start < sigAlgs.size()) {
      size_t end = sigAlgs.find(':', start);
      if (end == std::string::npos) end = sigAlgs.size();
      std::string alg = sigAlgs.substr(start, end - start);
      if (!kAllowed.count(alg)) {
        throw std::runtime_error("Disallowed or risky signature algorithm: " + alg);
      }
      start = end + 1;
    }

    // At this point, only strong / approved algorithms are accepted.
    configuredSigAlgs_ = sigAlgs;
  }

 private:
  std::string configuredSigAlgs_;
};

