    secp384r1,
    secp521r1,
    x25519
};

// Map user-provided string to a safe, whitelisted KEM.
// Any non‑whitelisted or legacy algorithm (e.g., "secp192r1", "rsa1024")
// is rejected to avoid CWE-327 (use of broken/risky algorithms).
inline KEMId toKEMId(const std::string& kemStr) {
    if (kemStr == "secp256r1") return KEMId::secp256r1;
    if (kemStr == "secp384r1") return KEMId::secp384r1;
    if (kemStr == "secp521r1") return KEMId::secp521r1;
    if (kemStr == "x25519")    return KEMId::x25519;

    // Fail closed on unknown or insecure values.
    throw std::invalid_argument("Unsupported or insecure KEM: " + kemStr);
}

