// Secure pattern: use modern, non-broken primitives and verify MAC before decryption.
Status aeadDecrypt(ConstDataRange key,        // key = encKey || macKey (256b + 256b)
                   ConstDataRange in,         // in = iv || ciphertext || hmac
                   ConstDataRange ad,         // associated data
                   DataRange out) {
    constexpr size_t kAesKeySize   = 32;      // 256-bit AES
    constexpr size_t kMacKeySize   = 32;      // 256-bit HMAC key
    constexpr size_t kTagSize      = 32;      // 256-bit HMAC-SHA256 tag
    constexpr size_t kIvSize       = 16;      // AES block size

    if (key.length() != kAesKeySize + kMacKeySize)
        return Status(ErrorCodes::BadValue, "Invalid key size");

    if (in.length() < kIvSize + kTagSize)
        return Status(ErrorCodes::BadValue, "Ciphertext too short");

    // Split input:  [ iv | ciphertext | tag ]
    auto [ivAndCt, tagRange] = in.split(in.length() - kTagSize);
    auto [ivRange, ctRange]  = ivAndCt.split(kIvSize);

    // Derive separate keys (no key reuse between ENC and MAC)
    const uint8_t* encKey = key.data<uint8_t>();
    const uint8_t* macKey = encKey + kAesKeySize;

    // Compute and verify HMAC-SHA256 over (AD || iv || ciphertext)
    SHA256Block mac =
        SHA256Block::computeHmac(macKey, kMacKeySize, {ad, ivAndCt});
    if (!consttimeMemEqual(mac.data<uint8_t>(),
                           tagRange.data<const uint8_t>(),
                           kTagSize)) {
        return Status(ErrorCodes::BadValue, "Authentication failed");
    }

    // Only decrypt after MAC verification (encrypt-then-MAC)
    SymmetricKey aesKey(encKey, kAesKeySize, aesAlgorithm, "aesKey", 1);
    return _aesDecrypt(aesKey, aesMode::cbc, ivAndCt, out); // AES-256-CBC as strong primitive
}

