// Secure pattern: use strong, modern algorithms (e.g., SHA-256 + P-256 ECDSA)
// and avoid deprecated / broken ones (e.g., MD5, SHA-1, RSA with small keys).

#include <crypto/CHIPCryptoPAL.h>

using namespace chip;

// Signs data with P-256 ECDSA and SHA-256; no broken algorithms are used.
CHIP_ERROR SecureSignWithP256(const ByteSpan & message,
                              Crypto::P256Keypair & signerKeypair,
                              Crypto::P256ECDSASignature & outSignature)
{
    // ECDSA over NIST P-256 curve (strong, widely recommended)
    // Hash is SHA-256 internally (no MD5/SHA-1, which would violate CWE-327).
    return signerKeypair.ECDSA_sign_msg(message.data(), message.size(), outSignature);
}

// Example of computing a strong digest (avoid MD5 / SHA-1)
CHIP_ERROR SecureDigestSHA256(const ByteSpan & message,
                              MutableByteSpan & outDigest)
{
    // outDigest must be at least Crypto::SHA256::kDigestLength bytes
    VerifyOrReturnError(outDigest.size() >= Crypto::SHA256::kDigestLength, CHIP_ERROR_BUFFER_TOO_SMALL);

    Crypto::SHA256 sha256;
    ReturnErrorOnFailure(sha256.Begin());
    ReturnErrorOnFailure(sha256.AddData(message.data(), message.size()));
    ReturnErrorOnFailure(sha256.Finish(outDigest.data()));

    outDigest.reduce_size(Crypto::SHA256::kDigestLength);
    return CHIP_NO_ERROR;
}

