// Secure pattern: use a modern, well-vetted KDF + hash (HKDF + SHA-256)
// to derive multiple session keys from a shared secret, instead of
// using deprecated or weak algorithms (e.g., MD5, SHA-1, RC4, DES).

#include <cstdint>
#include <cstring>

// Pseudo-interfaces to keep this example simple and self‑contained.
using ByteSpan = struct { const uint8_t * data; size_t size; };

bool HKDF_SHA256(const uint8_t *secret, size_t secretLen,
                 const uint8_t *salt,   size_t saltLen,
                 const uint8_t *info,   size_t infoLen,
                 uint8_t *outKey,       size_t outKeyLen);

bool DeriveSessionKeys(const ByteSpan &secret,
                       const ByteSpan &salt,
                       const ByteSpan &info,
                       uint8_t *clientToServerKey, // 16 bytes
                       uint8_t *serverToClientKey) // 16 bytes
{
    constexpr size_t kKeySize    = 16;                      // AES-128
    constexpr size_t kTotalBytes = 2 * kKeySize;           // two keys
    uint8_t keyMaterial[kTotalBytes];

    // Use HKDF with SHA-256 (secure) instead of a broken or risky algorithm
    if (!HKDF_SHA256(secret.data, secret.size,
                     salt.data,   salt.size,
                     info.data,   info.size,
                     keyMaterial, sizeof(keyMaterial)))
