        return false;
    }

    // Split HKDF output into two independent AES-128 keys
    std::memcpy(clientToServerKey, keyMaterial,              kKeySize);
    std::memcpy(serverToClientKey, keyMaterial + kKeySize,   kKeySize);
    std::memset(keyMaterial, 0, sizeof(keyMaterial)); // clear sensitive data

    return true;
}

