result<void> parse_signing_certificate_v2_hash_algo(ASN1Reader& asn1r) {
  constexpr const char* kDefaultAlgo = "id-sha256";

  // Attempt to read the AlgorithmIdentifier
  auto alg = asn1r.read_alg();
  if (!alg) {
    // If the field is absent, enforce a strong default (SHA‑256)
    LIEF_DEBUG("hashAlgorithm not specified, using secure default: {}", kDefaultAlgo);
    // Optionally advance over an empty or defaulted SEQUENCE if required by format
    if (!asn1r.read_tag(MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE)) {
      LIEF_INFO("Malformed default hashAlgorithm sequence: {} (pos: {:d})",
                asn1r.get_str_tag(), asn1r.stream_pos());
      return make_error_code(lief_errors::read_error);
    }
    return {};
  }

  // Explicit algorithm provided: validate and reject weak ones
  const std::string& algo = *alg;
  if (algo == "id-md5" || algo == "id-sha1") {
    LIEF_INFO("Rejected weak hash algorithm in SigningCertificateV2: {}", algo);
    return make_error_code(lief_errors::crypto_weak_algo);
  }

  // Accept only algorithms from an allowlist (e.g., SHA‑256 / SHA‑384 / SHA‑512)
  if (algo != "id-sha256" && algo != "id-sha384" && algo != "id-sha512") {
    LIEF_INFO("Unknown or unsupported hash algorithm: {}", algo);
    return make_error_code(lief_errors::crypto_unsupported_algo);
  }

  LIEF_DEBUG("Using strong hash algorithm for SigningCertificateV2: {}", algo);
  return {};
}

