#include <stdexcept>
#include <string>
#include <vector>
#include <algorithm>

// Very small, self-contained example of rejecting weak cryptographic algorithms.
class SSLContext {
 public:
  // Throws if any requested signature algorithm is weak or unsupported.
  void setSigAlgsOrThrow(const std::string& sigAlgs) {
    if (sigAlgs.empty()) {
      throw std::runtime_error("Signature algorithm list cannot be empty");
    }

    // Allow-list of strong algorithms only (examples).
    static const std::vector<std::string> kAllowed = {
        "rsa_pss_rsae_sha256",
        "rsa_pss_rsae_sha384",
        "rsa_pss_rsae_sha512",
        "ECDSA+SHA256",
        "ECDSA+SHA384",
        "ECDSA+SHA512",
    };

    // Split on ':' and validate each algorithm against allow-list.
    size_t start = 0;
    while (start < sigAlgs.size()) {
      size_t pos = sigAlgs.find(':', start);
      std::string alg = sigAlgs.substr(
          start, (pos == std::string::npos) ? std::string::npos : pos - start);

      auto it = std::find(kAllowed.begin(), kAllowed.end(), alg);
      if (it == kAllowed.end()) {
        throw std::runtime_error("Rejected weak or unknown algorithm: " + alg);
      }

      if (pos == std::string::npos) break;
      start = pos + 1;
    }

    // If we reach here, all algorithms are strong and accepted.
    configuredSigAlgs_ = sigAlgs;
  }

 private:
  std::string configuredSigAlgs_;
};

