void UseCipherSecurely(const std::string& algoName,
                       const std::vector<uint8_t>& key,
                       const std::vector<uint8_t>& iv) {
    // 1. Allow only strong, known algorithms (positive allow‑list)
    if (algoName != "aes_256_gcm" && algoName != "chacha20_poly1305") {
        throw std::runtime_error("Unknown or disallowed cipher algorithm: " + algoName);
    }

