bool ValidateRequestedAlgorithm(const TString& jsonContent) {
    NJson::TJsonValue json;
    if (!NJson::ReadJsonTree(jsonContent, &json)) {
        Reply(Ydb::StatusIds::BAD_REQUEST, "Invalid JSON");
        return false;
    }

    // Allowed strong algorithms only
    static const THashSet<TString> kAllowedAlgos = {
        "sha256",
        "sha384",
        "sha512"
    };

    const auto& algo = json["checksum_algorithm"];
    if (!algo.IsDefined()) {
        Reply(Ydb::StatusIds::BAD_REQUEST, "Missing checksum_algorithm field");
        return false;
    }

    const TString algoName = algo.GetString();
    if (!kAllowedAlgos.contains(algoName)) {
        // Reject weak or unknown algorithms (e.g., "md5", "sha1")
        Reply(
            Ydb::StatusIds::BAD_REQUEST,
            TStringBuilder() << "Unsupported or insecure checksum algorithm: " << algoName
        );
        return false;
    }

    // Store validated algorithm for later cryptographic operations
    SelectedChecksumAlgorithm = algoName;
    return true;
}

