#ifdef _WIN32
  #include <windows.h>
  #include <bcrypt.h>
  #pragma comment(lib, "bcrypt.lib")
#else
  #include <random>
#endif

// Fills 'out' with cryptographically secure random bytes
inline void secure_random_bytes(std::uint8_t* out, std::size_t len) {
#ifdef _WIN32
    NTSTATUS status = BCryptGenRandom(
        nullptr,                // use system-preferred RNG
        out,
        static_cast<ULONG>(len),
        BCRYPT_USE_SYSTEM_PREFERRED_RNG
    );
    if (status != 0) {
        throw std::system_error(
            status, std::system_category(),
            "BCryptGenRandom failed"
        );
    }
#else
    std::random_device rd;      // non-deterministic, crypto-grade on most libs
    for (std::size_t i = 0; i < len; ++i) {
        out[i] = static_cast<std::uint8_t>(rd());
    }
#endif
}

// Example: get a secure 32-bit random value (avoids std::rand, weak RNGs, etc.)
inline std::uint32_t secure_random_u32() {
    std::uint32_t v;
    secure_random_bytes(reinterpret_cast<std::uint8_t*>(&v), sizeof(v));
    return v;
}

