// Secure pattern: use HMAC with a strong hash (SHA-256) instead of weak/broken algorithms.
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <vector>
#include <stdexcept>

std::vector<unsigned char> hmac_sha256(
    const unsigned char* data, size_t data_len,
    const unsigned char* key,  size_t key_len)
{
    unsigned int len = EVP_MAX_MD_SIZE;
    std::vector<unsigned char> mac(len);

    // Use a modern, strong digest: SHA-256
    const EVP_MD* md = EVP_sha256();
    if (!md) throw std::runtime_error("EVP_sha256 unavailable");

    // HMAC() is a simple, recommended wrapper in OpenSSL
    unsigned char* result = HMAC(
        md, key, static_cast<int>(key_len),
        data, data_len,
        mac.data(), &len);

    if (!result) throw std::runtime_error("HMAC computation failed");
    mac.resize(len);  // Trim to actual length
    return mac;
}

