// Secure pattern: use a modern, standardized algorithm (AES-256 in this case)
// via a vetted crypto library (OpenSSL EVP) instead of deprecated / weak ciphers.

#include <openssl/evp.h>
#include <vector>

bool EncryptWithAes256Cbc(
    const std::vector<unsigned char>& plaintext,
    const std::vector<unsigned char>& key,   // 32 bytes (256-bit)
    const std::vector<unsigned char>& iv,    // 16 bytes
    std::vector<unsigned char>& ciphertext)
{
    if (key.size() != 32 || iv.size() != 16) return false;

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return false;

    bool ok = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr,
                                 key.data(), iv.data());
    if (!ok) { EVP_CIPHER_CTX_free(ctx); return false; }

    ciphertext.resize(plaintext.size() + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    int outLen1 = 0, outLen2 = 0;

    ok = EVP_EncryptUpdate(ctx, ciphertext.data(), &outLen1,
                           plaintext.data(),
                           static_cast<int>(plaintext.size()));
    if (!ok) { EVP_CIPHER_CTX_free(ctx); return false; }

    ok = EVP_EncryptFinal_ex(ctx, ciphertext.data() + outLen1, &outLen2);
    EVP_CIPHER_CTX_free(ctx);
    if (!ok) return false;

    ciphertext.resize(outLen1 + outLen2);
    return true;
}

