// Secure pattern: Only forward requests to hosts on an explicit allow‑list.
void HandleProxyRequest(const NHttp::THttpIncomingRequestPtr& incoming) {
    const TString allowedProxyHost{"ydb.viewer.page"};

    // Parse target host/path from incoming URL:  /<host>/<path...>
    TString url = incoming->URL;                 // e.g. "/ydb.viewer.page/counters"
    if (!url.StartsWith("/")) {
        RejectRequest(400, "Bad Request");
        return;
    }

    // Extract first path segment as target host
    size_t secondSlash = url.find('/', 1);
    TString targetHost = url.SubStr(1, secondSlash == TString::npos
                                        ? url.size() - 1
                                        : secondSlash - 1);
    TString targetPath = secondSlash == TString::npos
                             ? "/"
                             : url.SubStr(secondSlash);

    // Enforce strict allow‑list
    if (targetHost != allowedProxyHost) {
        RejectRequest(403, "Forbidden");
        return;
    }

    // Build safe outgoing request
    NHttp::THttpOutgoingRequestPtr outgoing = new NHttp::THttpOutgoingRequest();
    outgoing->Method = incoming->Method;        // e.g. "OPTIONS", "GET"
    outgoing->Host   = allowedProxyHost;        // cannot be user‑controlled
    outgoing->URL    = targetPath;              // only path portion

    ForwardToBackend(outgoing);                 // performs the actual HTTP call
}

