// Secure pattern: validate and restrict target URL before issuing any HTTP request
bool isAllowedUrl(const QUrl &url)
{
  // 1) URL must be valid and absolute
  if ( !url.isValid() || !url.isRelative() == false )
    return false;

  // 2) Only allow http/https
  if ( url.scheme() != QLatin1String("http") &&
       url.scheme() != QLatin1String("https") )
    return false;

  // 3) Only allow calls to a trusted host
  static const QStringList allowedHosts = { QStringLiteral("api.example.com") };
  if ( !allowedHosts.contains(url.host(), Qt::CaseInsensitive) )
    return false;

  return true;
}

void ExternalStorageWidget::storeFileSecure(const QString &urlExpression)
{
  QString evaluated = evaluateUrlExpression(urlExpression);
  QUrl targetUrl(evaluated);

  // If expression is invalid or URL not allowed, abort before any request
  if ( evaluated.isEmpty() || !isAllowedUrl(targetUrl) )
  {
    logWarning("Blocked external request: invalid or untrusted URL.");
    return;
  }

  // Safe to proceed: send request only to validated, whitelisted endpoint
  QNetworkRequest req(targetUrl);
  networkAccessManager->post(req, fileContentToUpload());
}

