#include <QUrl>
#include <QString>

// Convert a user-supplied "imagePath" into a safe URL.
// Only allow:
//   - Qt resource URLs (qrc:)
//   - Local file URLs
// Reject any remote/network URLs (http, https, ftp, etc.).
QUrl safeImagePathToUrl(const QString &imagePath)
{
    // Handle Qt resource paths (":/icons/img.png" -> "qrc:/icons/img.png")
    if (imagePath.startsWith(':')) {
        QUrl url;
        url.setScheme(QStringLiteral("qrc"));
        url.setPath(imagePath.mid(1)); // drop leading ':'
