// Convert a user-supplied "imagePath" into a safe URL.
// Only allow:
//   - Qt resource URLs (qrc:)
//   - Local file URLs
// Reject any remote/network URLs (http, https, ftp, etc.).
QUrl safeImagePathToUrl(const QString &imagePath)
{
    // Handle Qt resource paths (":/icons/img.png" -> "qrc:/icons/img.png")
    if (imagePath.startsWith(':')) {
        QUrl url;
        url.setScheme(QStringLiteral("qrc"));
        url.setPath(imagePath.mid(1)); // drop leading ':'
        return url;
    }

    // Treat everything else as a local file path, not a network URL.
    QUrl url = QUrl::fromLocalFile(imagePath);

    // Extra safety: ensure we did not accidentally create a remote URL.
    if (url.isRelative() || url.isLocalFile())
        return url;

    // If for any reason this resolves to a non-local URL, reject it.
    return QUrl(); // invalid URL => caller must handle as error
}

