// Secure pattern against SSRF / unwanted local-file access
std::string SecureResolvePath(const std::string &uri,
                              const std::string &rootDir)
{
    // 1. Normalize/convert URI if possible (may return same string)
    const std::string resolved = VSIURIToVSIPath(uri);
    if (resolved != uri)
        return resolved;

    // 2. Relative paths are anchored under a trusted root directory
    if (CPLIsFilenameRelative(uri.c_str()))
        return CPLFormFilenameSafe(rootDir.c_str(), uri.c_str(), nullptr);

    // 3. Block remote → local access by default
    const bool isLocalTarget = VSIIsLocal(uri.c_str());
    const bool isRemoteContext = !VSIIsLocal(rootDir.c_str());
    if (isLocalTarget && isRemoteContext)
    {
        const char *opt =
            CPLGetConfigOption("ALLOW_REMOTE_TO_LOCAL_ACCESS", nullptr);

        // If not explicitly allowed, deny and log
        if (opt == nullptr || !CPLTestBool(opt))
        {
            CPLError(CE_Failure, CPLE_AppDefined,
                     "Blocked access: remote context '%s' tried to open "
                     "local resource '%s'. Explicit opt required.",
                     rootDir.c_str(), uri.c_str());
            return std::string(); // deny
        }
    }

    // 4. Fallback: return as-is (non-local or same-context local)
    return uri;
}

