// Only allow connections to devices that appear in the trusted whitelist.
// This prevents arbitrary upstream addresses (SSRF).
bool LedDeviceYeelight::updateLights(const QVector<yeelightAddress> &trustedList)
{
    if (_lightsAddressList.empty())
        return false;

    _lights.clear();
    _lights.reserve(static_cast<ulong>(_lightsAddressList.size()));

    // Build a fast lookup set of trusted (host, port) pairs
    QSet<yeelightAddress> trustedSet = QSet<yeelightAddress>::fromList(trustedList.toList());

    for (const auto &deviceAddr : _lightsAddressList)
    {
        // Reject any address not explicitly whitelisted
        if (!trustedSet.contains(deviceAddr))
        {
            Warning(_log,
                    "Rejected non-whitelisted light address %s:%d",
                    QSTRING_CSTR(deviceAddr.host),
                    deviceAddr.port);
            continue;
        }

        Debug(_log,
              "Adding whitelisted Yeelight %s:%d",
              QSTRING_CSTR(deviceAddr.host),
              deviceAddr.port);

        // Only connect to validated, whitelisted destination
        _lights.emplace_back(_log, deviceAddr.host, deviceAddr.port);
    }

    setLightsCount(static_cast<uint>(_lights.size()));
    return !_lights.empty();
}

