enum class ProtocolVersion { IPV4, IPV6 };

struct OpaqueAddr {
    std::string Ip;  // e.g. "127.0.0.1" or "::1"
    int Port;
    bool IsV4() const { return Ip.find(':') == std::string::npos; }
    bool IsV6() const { return !IsV4(); }
};

std::vector<OpaqueAddr> FilterByProtocol(
    const std::vector<OpaqueAddr>& resolved,
    ProtocolVersion requested)
{
    std::vector<OpaqueAddr> allowed;
    for (const auto& addr : resolved) {
        if (requested == ProtocolVersion::IPV4 && addr.IsV4()) {
            allowed.push_back(addr);
        } else if (requested == ProtocolVersion::IPV6 && addr.IsV6()) {
            allowed.push_back(addr);
        }
    }
    if (allowed.empty()) {
        throw std::runtime_error("No address for requested protocol");
    }
    return allowed;
}

