// Secure pattern: only handle requests whose URL is on a strict allowlist.
// Any unknown / unregistered URL is rejected and never used to make outbound calls.

class TSecureRequestHandler {
public:
    void HandleIncoming(const TNetworkRequest& req) {
        // Allowlist of server-supported endpoints
        static const THashSet<TString> AllowedUrls = {
            "/status",
            "/metrics",
            "/check_stop"
        };

        // Reject anything not explicitly allowed
        if (!AllowedUrls.contains(req.Url)) {
            SendError(req.ReqId, "Unsupported endpoint");
            return;
        }

        // Dispatch only known-safe URLs to internal processors
        auto it = CmdProcessors.find(req.Url);
        if (it == CmdProcessors.end()) {
            SendError(req.ReqId, "Handler not configured");
            return;
        }

        // Safe: URL is validated, mapped to a fixed handler, not used as a raw target
        it->second->ProcessRequest(req);
    }

private:
    THashMap<TString, ICmdProcessor*> CmdProcessors;

    void SendError(TReqId id, const TString& msg) {
        TNetworkResponse resp;
        resp.ReqId = id;
        resp.Status = TNetworkResponse::EStatus::Error;
        resp.Data.assign(msg.begin(), msg.end());
        Requester->SendResponse(id, &resp.Data);
    }
};

