// Secure pattern: normalize and validate URL-like input before any server-side use
#include <string>
#include <regex>
#include <cassert>

// Extracts only a safe identifier (e.g., username / page id) from a URL-like string
std::string ExtractSafeId(std::string const & urlLike)
{
  // Accept alphanumerics, underscore, dot, and dash as a conservative identifier
  static const std::regex kSafeIdRegex(R"(([A-Za-z0-9_.-]{1,64})$)");
  std::smatch m;

  // Strip protocol and domain and keep only the last path segment or query part
  auto pos = urlLike.find_last_of("/?");
  std::string tail = (pos == std::string::npos) ? urlLike : urlLike.substr(pos + 1);

  if (std::regex_match(tail, m, kSafeIdRegex))
    return m[1].str();          // safe normalized identifier

  return {};                    // invalid / unsafe -> reject or log
}

int main()
{
  std::string rawFacebook = "https://www.facebook.com/PierreCardinPeru.oficial/";
  std::string rawLine     = "https://line.me/R/ti/p/%40015qevdv";

  std::string fbId   = ExtractSafeId(rawFacebook);
  std::string lineId = ExtractSafeId(rawLine);

  assert(fbId   == "PierreCardinPeru.oficial");
  assert(lineId == "015qevdv");

  // Only use fbId / lineId in server-side logic (e.g., lookups),
  // never the original attacker-controlled URLs, preventing SSRF.
}

