// Secure SRV record validation to prevent SSRF (CWE-918)
bool IsSrvRecordTargetAllowed(const QueryRecordInfo::Record &record,
                              const char                  *expectedHost)
{
    // Only allow SRV records that resolve to the exact, pre‑approved host.
    // No arbitrary hostnames or user‑supplied targets are permitted.

    if (record.mDataBuffer == nullptr || expectedHost == nullptr)
    {
        return false;
    }

    // Allocate temporary message buffer for SRV record parsing
    Message *msg = sInstance->Get<MessagePool>().Allocate(Message::kTypeOther);
    if (msg == nullptr)
    {
        return false;
    }

    uint16_t offset = sizeof(Dns::SrvRecord) - sizeof(Dns::ResourceRecord);

    // Copy raw SRV record bytes into the message buffer
    if (msg->AppendBytes(record.mDataBuffer, record.mRecordLength) != kErrorNone)
    {
        msg->Free();
        return false;
    }

    // Compare uncompressed target host name with a strict allowlisted value
    if (Dns::Name::CompareName(*msg, offset, expectedHost) != kErrorNone)
    {
        msg->Free();
        return false;   // Reject if hostname does not match the allowed target
    }

    // Ensure there is no trailing data after the host name
    if (offset != msg->GetLength())
    {
        msg->Free();
        return false;
    }

    msg->Free();
    return true;        // Safe to use this SRV target for outbound requests
}

