// Secure pattern against CWE-918 (SSRF):
// 1. Use a fixed, trusted base URL (host cannot be changed by user input).
// 2. Only append validated path segments or query parameters.
// 3. Do NOT allow user input to control the scheme, host, or port.

#include <QString>
#include <QUrl>

QString buildSwiftUrl(const QString &internalName)
{
    // Base URL is hard-coded and trusted
    const QUrl baseUrl("https://swift.gsfc.nasa.gov/archive/grb_table/");

    // Derive path segment from internal data (not directly from user input)
    QString safeName = internalName;
    safeName.replace("GRB", "");        // Example normalization
    safeName.remove("..");              // Remove path traversal patterns
    safeName = QUrl::toPercentEncoding(safeName);

    // Construct final URL by appending only a path segment
    QUrl finalUrl = baseUrl.resolved(QUrl(safeName + ".html"));

    // Optional: ensure host is still the expected one (defense in depth)
    if (finalUrl.host() != "swift.gsfc.nasa.gov")
        return QString(); // or handle error

    return finalUrl.toString();
}

