// Secure pattern: validate target IP and port against an allowlist before use.
struct AllowedTarget {
  std::string ip_start;
  std::string ip_end;
  int32_t     port_start;
  int32_t     port_end;
};

bool is_target_allowed(const std::string &ip,
                       int32_t port,
                       const std::vector<AllowedTarget> &allowlist)
{
  if (allowlist.empty()) {
    return false; // no fallback: deny by default
  }

  for (const auto &entry : allowlist) {
    // simple lexicographical IP range check (assumes normalized IP strings)
    if (ip >= entry.ip_start && ip <= entry.ip_end &&
        port >= entry.port_start && port <= entry.port_end) {
      return true;
    }
  }
  return false;
}

// Usage before making any outbound request (HTTP, DB, etc.)
void perform_request(const std::string &ip, int32_t port)
{
